@auto_docstring
class SDARMRPModel(SDARMRPPreTrainedModel, GenerationMixin):

    # _tied_weights_keys = [
    #     # "lm_head.weight",
    # ]
    # _tp_plan = {"lm_head": "colwise_rep"}
    # _pp_plan = {"lm_head": (["hidden_states"], ["logits"])}

    def __init__(self, config, layer_offset: Optional[int] = None):
        super().__init__(config)
        self.model = SDARMRPBaseModel(config, layer_offset=layer_offset)
        self.vocab_size = config.vocab_size

        # Initialize weights and apply final processing
        self.post_init()
        
    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        embed_tokens = None,
        lm_head = None,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        logits_to_keep: Union[int, torch.Tensor] = 0,
        use_mrp: bool = True,
        **kwargs: Unpack[KwargsForCausalLM],
    ) -> CausalLMOutputWithPast:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.

        Example:

        ```python
        >>> from transformers import AutoTokenizer, SDARForCausalLM

        >>> model = SDARForCausalLM.from_pretrained("DiffuOpen/SDAR-1.7B-Chat")
        >>> tokenizer = AutoTokenizer.from_pretrained("DiffuOpen/SDAR-1.7B-Chat")

        >>> prompt = "Hey, are you conscious? Can you talk to me?"
        >>> inputs = tokenizer(prompt, return_tensors="pt")

        >>> # Generate
        >>> generate_ids = model.generate(inputs.input_ids, max_length=30)
        >>> tokenizer.batch_decode(generate_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        "Hey, are you conscious? Can you talk to me?\nI'm not conscious, but I can talk to you."
        ```"""
        assert not self.training, "The forward method of SDARMRPForCausalLM is not designed for training. Please use the `prepare_for_bd_training` method to prepare your inputs for training, and then call the forward method with the prepared inputs for inference."
        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        # decoder outputs consists of (dec_features, layer_state, dec_hidden, dec_attn)
        outputs: BaseModelOutputWithPast = self.model(
            embed_tokens=embed_tokens,
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            output_attentions=output_attentions,
            output_hidden_states=output_hidden_states,
            cache_position=cache_position,
            **kwargs,
        )

        hidden_states = outputs.last_hidden_state
        # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
        slice_indices = slice(-logits_to_keep,
                            None) if isinstance(logits_to_keep, int) else logits_to_keep
        hidden_states = hidden_states[:, slice_indices, :].contiguous()
        fuse_linear_and_cross_entropy = self.config.fuse_cross_entropy and self.training
        if fuse_linear_and_cross_entropy:
            # When using fused_linear_ce_loss, we do not compute the whole logits on HBM
            logits = None
        else:
            # Bypass accelerate hooks on lm_head (same reason as embed_tokens above)
            logits = lm_head(hidden_states.to(lm_head.weight.device))

        loss = None
        if labels is not None:
            # FusedLinearCrossEntropyLoss will be implemented by monkey patch when training
            # We don't use it when inferencing
            loss_fct = nn.CrossEntropyLoss()  # nn.CE
            loss = loss_fct(
                logits.view(-1, self.config.vocab_size), labels.view(-1))

        return CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
        )


def freeze_module(m):
    if m is None:
        return
    m.eval()
    for p in m.parameters(recurse=True):
        p.requires_grad_(False)

def show_require_grad(module):
    for name, param in module.named_parameters():
        print(f"{name} | {param.requires_grad}")

@auto_docstring
class SDARMRPForCausalLM(SDARMRPPreTrainedModel, GenerationMixin):
    _tied_weights_keys = ["lm_head.weight", "mrp_modules.0.lm_head.weight", "mrp_modules.0.model.embed_tokens.weight"]
    _tp_plan = {"lm_head": "colwise_rep"}
    _pp_plan = {"lm_head": (["hidden_states"], ["logits"])}

    def __init__(self, config):
        super().__init__(config)
        self.model = SDARModel(config)
        self.mrp_modules = nn.ModuleList([
            SDARMRPModel(
                config,
                layer_offset=config.num_hidden_layers + h * config.num_nextn_predict_layers,
            )
            for h in range(config.num_mrp_heads)
        ])
        self.vocab_size = config.vocab_size
        self.lm_head = nn.Linear(
            config.hidden_size, config.vocab_size, bias=False)

        # freeze_module(self.model)
        # freeze_module(self.lm_head)

        # Initialize weights and apply final processing
        self.post_init()
        self.input_prep_mode = "infer_matched"

        # Loss function: configurable via set_loss_type(). Default: "ce"
        self.loss_fn = build_loss_function("ce")

        # MRP profiling: stash per-step metrics for trainer to log. Off by default.
        self._profile_mrp_metrics: bool = False
        self._mrp_step_metrics: dict = {}

        # TPF (tokens-per-target-forward) profiling for inference. Off by default.
        # When enabled, generate() populates self._last_tpf_stats with counters and
        # per-sample breakdowns so callers can compute realized decoding throughput.
        self._profile_tpf: bool = False
        self._last_tpf_stats: Optional[dict] = None

        # Token reveal mode during training: "gt" reveals random positions per
        # block; "gt_random" samples a per-block reveal count. Both fill revealed
        # positions with the ground-truth label.
        self.reveal_mode: str = "gt"

        # For reveal_mode == "gt": number of random positions to reveal per block
        # (each position is drawn independently via per-block amax over uniform
        # scores). Default 1 matches the historical single-token behaviour.
        self.gt_topk: int = 1

        # For reveal_mode == "gt_random": candidate reveal counts. One count is
        # sampled independently for each active block, so different blocks in the
        # same sequence can reveal different numbers of ground-truth tokens.
        self.gt_random_topk: Tuple[int, ...] = (1,)

        # Multi-step MRP training: K = self.mrp_steps controls how many
        # (reveal -> no_grad target forward -> MRP forward) rounds are chained
        # per training step. At each step k (k=1..K), the MRP head receives
        # acc_{k-1} = h_A + Σ_{i<k} h_p_i as inputs_embeds and is supervised so
        # that lm_head(acc_{k-1} + h_p_k) ≈ lm_head(h_T_k) — exactly the
        # logits_sum inference semantics. K=1 is identical to the original
        # single-step training path. Loss across the K per-step losses is
        # combined by self.loss_weight_mode.
        self.mrp_steps: int = 1
        self.loss_weight_mode: str = "uniform"

    def get_input_embeddings(self):
        return self.model.embed_tokens

    def set_input_embeddings(self, value):
        self.model.embed_tokens = value
        for m in self.mrp_modules:
            m.model.embed_tokens = value

    def get_output_embeddings(self):
        return self.lm_head

    def set_output_embeddings(self, new_embeddings):
        self.lm_head = new_embeddings
        for m in self.mrp_modules:
            m.lm_head = new_embeddings
        
    def set_loss_type(self, loss_type: str = "ce", kd_temperature: float = 1.0, kd_reverse_kl: bool = False):
        """Configure the training loss function.

        Args:
            loss_type: "ce", "ce_sum", "kd_diff", "kd_diff_sum", "mse", or "mse_sum".
            kd_temperature: Temperature for KD softmax.
            kd_reverse_kl: Use reverse KL (mode-seeking) instead of forward KL.
        """
        self.loss_fn = build_loss_function(loss_type, kd_temperature, kd_reverse_kl)

    def set_mrp_profile_metrics(self, enabled: bool = True) -> None:
        """Enable or disable per-step MRP profiling metrics (logged under 'mrp/' prefix)."""
        self._profile_mrp_metrics = enabled
        print(f"[MRPProfile] Profiling metrics {'enabled' if enabled else 'disabled'}.")

    def set_tpf_profiling(self, enabled: bool = True) -> None:
        """Enable or disable TPF (tokens-per-target-forward) profiling in ``generate()``.

        When enabled, each call to ``generate()`` populates ``self._last_tpf_stats``
        with a dict of counters and per-sample token accounting. The main metric is
        ``tpf_denoising`` = total tokens committed / number of target-model forward
        calls inside the denoising loop. Prefill and store-KV forwards are counted
        separately so end-to-end TPF can also be computed.

        In batched eval, samples that emit stop tokens early become ``finished`` but
        the batch keeps running for the stragglers, so those trailing forwards cost
        wall-clock but commit 0 tokens for the finished samples. The per-sample and
        per-forward ``active_samples`` tallies surface exactly how much this drags
        down the realized TPF versus the ideal ``batch_size * (1 + mrp_steps)``.
        """
        self._profile_tpf = enabled
        if not enabled:
            self._last_tpf_stats = None
        print(f"[TPFProfile] TPF profiling {'enabled' if enabled else 'disabled'}.")

    def set_input_prep_mode(self, input_prep_mode: str = "infer_matched"):
        if input_prep_mode not in TRAINING_INPUT_PREP_MODES:
            raise ValueError(
                f"Unknown input_prep_mode '{input_prep_mode}'. "
                f"Supported: {sorted(TRAINING_INPUT_PREP_MODES)}"
            )
        self.input_prep_mode = input_prep_mode

    def set_mrp_init_std(self, init_std: float = 0.02):
        """Initialize MRP head weights with normal_(mean=0, std=init_std).

        Forks the RNG and reseeds locally so mrp_modules[0]'s init is identical
        across num_mrp_heads configs. Without this, constructing extra
        SDARMRPModel instances in __init__ advances the default generator,
        giving head 0 a different random draw between 1h and Nh models even
        under the same seed.

        Args:
            init_std: Standard deviation for normal initialization. Default 0.02 matches
                      standard PyTorch init. Use e.g. 1e-4 for near-zero init.
        """
        with torch.random.fork_rng(devices=list(range(torch.cuda.device_count()))):
            torch.manual_seed(42)
            if torch.cuda.is_available():
                torch.cuda.manual_seed_all(42)
            for m in self.mrp_modules:
                for param in m.model.parameters():
                    nn.init.normal_(param, mean=0.0, std=init_std)

    def init_eh_proj_structured(self):
        """Structured init for eh_proj: W_h = identity, W_e = zero.

        eh_proj weight has shape (H, 2H) where first H cols correspond to
        enorm(embed(input_ids)) and last H cols to hnorm(hidden_states_A).
        Setting W_h=I, W_e=0 makes the MRP head start as a pass-through of A's
        hidden states, so C ~ 0 at init without killing gradient signal in
        the transformer layers.
        """
        with torch.no_grad():
            for m in self.mrp_modules:
                W = m.model.eh_proj.weight  # shape (H, 2H)
                H = W.shape[0]
                W[:, :H].zero_()           # W_e = 0 (embedding half)
                W[:, H:].copy_(torch.eye(H, dtype=W.dtype, device=W.device))  # W_h = I

    def set_reveal_mode(self, mode: str) -> None:
        """Set how revealed tokens are chosen during training.

        "gt"         (default): reveal ``gt_topk`` random positions per block,
                filled with the ground-truth label. Teacher forcing with uniform
                position coverage.
        "gt_random": sample a reveal count from ``gt_random_topk`` per block,
                then reveal that many random ground-truth positions in the block.
        """
        valid_modes = {"gt", "gt_random"}
        if mode not in valid_modes:
            raise ValueError(
                f"reveal_mode must be 'gt' or 'gt_random', got {mode!r}."
            )
        self.reveal_mode = mode

    def set_gt_topk(self, k: int) -> None:
        """Number of random positions to reveal per block per b-step in gt mode.

        Only used when ``reveal_mode == 'gt'``. Default 1 matches the historical
        single-random-token-per-block behaviour.
        """
        if k < 1:
            raise ValueError(f"gt_topk must be >= 1, got {k}.")
        self.gt_topk = int(k)

    def set_gt_random_topk(self, values) -> None:
        """Candidate reveal counts for ``reveal_mode == 'gt_random'``.

        Accepts a comma-separated string (for CLI use), a single integer, or a
        sequence of integers. One value is sampled independently per active block.
        """
        if isinstance(values, str):
            values = values.strip()
            if values.startswith("[") and values.endswith("]"):
                values = values[1:-1]
            choices = [int(item.strip()) for item in values.split(",") if item.strip()]
        elif isinstance(values, int):
            choices = [values]
        else:
            choices = [int(item) for item in values]

        if not choices:
            raise ValueError("gt_random_topk must contain at least one integer.")
        if any(choice < 1 for choice in choices):
            raise ValueError(f"gt_random_topk values must be >= 1, got {choices!r}.")
        self.gt_random_topk = tuple(choices)

    def set_mrp_steps(self, k: int) -> None:
        """Number of training-time MRP unroll steps (K). K=1 reproduces the
        original single-step training path. K>=2 chains K reveals and K MRP
        forwards with a hidden accumulator (acc_{k-1} = h_A + Σ_{i<k} h_p_i),
        supervising each step against a fresh no_grad target forward on the
        progressively denoised input.
        """
        k = int(k)
        if k < 1:
            raise ValueError(f"mrp_steps must be >= 1, got {k}.")
        self.mrp_steps = k
        if k == 1 and self.loss_weight_mode != "uniform":
            warnings.warn(
                f"loss_weight_mode={self.loss_weight_mode!r} has no effect when "
                f"mrp_steps=1 (single-step training); it is only applied for K>=2.",
                stacklevel=2,
            )

    def set_loss_weight_mode(self, mode: str) -> None:
        """How per-step losses L_k are combined when mrp_steps (K) >= 2.

        "uniform" (default): Loss = (1/K) * Σ L_k.
        """
        if mode not in {"uniform"}:
            raise ValueError(
                f"loss_weight_mode must be 'uniform', got {mode!r}."
            )
        self.loss_weight_mode = mode
        if self.mrp_steps == 1 and mode != "uniform":
            warnings.warn(
                f"loss_weight_mode={mode!r} has no effect when mrp_steps=1 "
                f"(single-step training); it is only applied for K>=2.",
                stacklevel=2,
            )

    def _mrp_anchor(self, target_outputs):
        """Return the MRP chain anchor (the target's final hidden state)."""
        # Prefer last_hidden_state (BaseModelOutputWithPast in training);
        # fall back to hidden_states[-1] for CausalLMOutputWithPast, which
        # the generation paths return and which lacks last_hidden_state.
        last = getattr(target_outputs, "last_hidden_state", None)
        if last is not None:
            return last
        return target_outputs.hidden_states[-1]

    def _build_step_supervision(
        self,
        *,
        sup_mask_end: torch.BoolTensor,
        pos_to_keep_end: torch.BoolTensor,
        labels_full: torch.LongTensor,
        p_mask_full: torch.Tensor,
        answer_len_full,
    ):
        """Pick the 2D supervision mask and per-step (labels, p_mask, answer_len).

        Only the still-masked positions at the end of the step are supervised;
        revealed positions are dropped from the loss and answer_len is shrunk by
        the corresponding 1/p_mask contributions.

        Returns ``(sup_mask_2d, labels_k, p_mask_k, answer_len_k)``.
        """
        chosen_sup_mask = sup_mask_end
        chosen_pos_to_keep = pos_to_keep_end

        # answer_len's 1/p_mask correction subtracts the contributions of
        # positions excluded from supervision relative to the original
        # diffusion-supervised set (= all already-revealed positions).
        if chosen_pos_to_keep.all():
            labels_k = labels_full
            p_mask_k = p_mask_full
            answer_len_k = answer_len_full
        else:
            labels_k = labels_full[chosen_pos_to_keep].contiguous()
            p_mask_k = p_mask_full[chosen_pos_to_keep].contiguous()
            revealed_mask = ~chosen_pos_to_keep
            answer_len_k = (
                answer_len_full
                - (1.0 / p_mask_full[revealed_mask].float()).sum()
            )
        return (chosen_sup_mask, labels_k, p_mask_k, answer_len_k)

    def set_decoder(self, decoder):
        self.model = decoder

    def get_decoder(self):
        return self.model
    
    # def tie_weights(self):
    #     Standard HF tie: lm_head.weight <-> model.embed_tokens.weight
    #     if getattr(self.config, "tie_word_embeddings", False):
    #         if self.get_output_embeddings() is not None and self.get_input_embeddings() is not None:
    #             self._tie_or_clone_weights(self.get_output_embeddings(), self.get_input_embeddings())

    #     # Reassert module sharing for the MRP module
    #     self.mrp_modules[0].model.embed_tokens = self.model.embed_tokens
    #     self.mrp_modules[0].lm_head = self.lm_head
        
    def _build_training_attention_masks(self, position_ids, input_prep_mode: Optional[str] = None, block_size: Optional[int] = None):
        input_prep_mode = input_prep_mode or self.input_prep_mode
        block_size = block_size or self.config.block_size
        num_tokens = calculate_token_nums(position_ids)
        if input_prep_mode == "bd_packed":
            attention_mask_dense = block_attn_mask(num_tokens, block_size, position_ids.device)
        elif input_prep_mode == "infer_matched":
            attention_mask_dense = block_causal_attn_mask(num_tokens, block_size, position_ids.device)
        else:
            raise ValueError(
                f"Unknown input_prep_mode '{input_prep_mode}'. "
                f"Supported: {sorted(TRAINING_INPUT_PREP_MODES)}"
            )
        flex_attention_mask_3d = create_flex_attention_mask(attention_mask_dense)
        return num_tokens, attention_mask_dense, flex_attention_mask_3d

    def _prepare_for_bd_training_result(self, inputs_ids, position_ids, prompt_mask):
        bsz, seq_len = inputs_ids.shape
        num_tokens = calculate_token_nums(position_ids) # List[torch.Tensor]
        noisy_inputs_ids, logits_to_keep_half, p_mask = forward_add_noise_packed(
            inputs_ids=inputs_ids,
            num_tokens_list=num_tokens,
            prompt_mask=prompt_mask,
            mask_id=self.config.mask_token_id,
        )
        router_noisy_part_list = []
        for i in range(bsz):
            cur_router_noisy_part = (torch.arange(num_tokens[i].shape[0] *2) % 2 == 0).to(inputs_ids.device)
            cur_router_noisy_part = cur_router_noisy_part.repeat_interleave(num_tokens[i].repeat_interleave(2))
            router_noisy_part_list.append(cur_router_noisy_part)
        router_noisy_part = torch.stack(router_noisy_part_list, dim=0)

        # concated inputs_ids: (bzs, seq_len x 2)
        concat_inputs_ids = inputs_ids.repeat(1, 2)
        # concated logits_to_keep: (bsz, seq_len x 2)
        logits_to_keep = torch.zeros(
                    bsz, 2 * seq_len, dtype=torch.bool, device=inputs_ids.device)
        # concated position_ids: (bsz, seq_len x 2)
        concat_position_ids = torch.zeros(
                    bsz, 2 * seq_len, dtype=position_ids.dtype, device=position_ids.device)
        for i in range(bsz):
            concat_inputs_ids[i][router_noisy_part[i]] = noisy_inputs_ids[i]
            concat_inputs_ids[i][~router_noisy_part[i]] = inputs_ids[i]

            logits_to_keep[i][router_noisy_part[i]] = logits_to_keep_half[i]

            concat_position_ids[i][router_noisy_part[i]] = position_ids[i]
            concat_position_ids[i][~router_noisy_part[i]] = position_ids[i]

        attention_mask_dense = block_attn_mask(num_tokens, self.config.block_size, inputs_ids.device)
        flex_attention_mask_3d = create_flex_attention_mask(attention_mask_dense)

        return TrainingPrepOutputs(
            input_ids=concat_inputs_ids,
            position_ids=concat_position_ids,
            attention_mask_dense=attention_mask_dense,
            attention_mask=flex_attention_mask_3d,
            logits_to_keep_half=logits_to_keep_half,
            logits_to_keep=logits_to_keep,
            p_mask=p_mask,
            original_position_ids=position_ids,
            input_prep_mode="bd_packed",
        )

    def prepare_for_bd_training(self, inputs_ids, position_ids, prompt_mask):
        prep = self._prepare_for_bd_training_result(inputs_ids, position_ids, prompt_mask)
        return (
            prep.input_ids,
            prep.position_ids,
            prep.attention_mask,
            prep.logits_to_keep_half,
            prep.logits_to_keep,
            prep.p_mask,
        )

    def _prepare_for_infer_matched_training_result(self, inputs_ids, position_ids, prompt_mask):
        noisy_inputs_ids, logits_to_keep_half, p_mask = forward_add_noise_packed(
            inputs_ids=inputs_ids,
            num_tokens_list=calculate_token_nums(position_ids),
            prompt_mask=prompt_mask,
            mask_id=self.config.mask_token_id,
        )
        _, attention_mask_dense, flex_attention_mask_3d = self._build_training_attention_masks(
            position_ids,
            input_prep_mode="infer_matched",
        )
        logits_to_keep = logits_to_keep_half.clone()
        return TrainingPrepOutputs(
            input_ids=noisy_inputs_ids,
            position_ids=position_ids,
            attention_mask_dense=attention_mask_dense,
            attention_mask=flex_attention_mask_3d,
            logits_to_keep_half=logits_to_keep_half,
            logits_to_keep=logits_to_keep,
            p_mask=p_mask,
            original_position_ids=position_ids,
            input_prep_mode="infer_matched",
        )

    def prepare_for_infer_matched_training(self, inputs_ids, position_ids, prompt_mask):
        prep = self._prepare_for_infer_matched_training_result(inputs_ids, position_ids, prompt_mask)
        return (
            prep.input_ids,
            prep.position_ids,
            prep.attention_mask,
            prep.logits_to_keep_half,
            prep.logits_to_keep,
            prep.p_mask,
        )

    def prepare_training_inputs(self, inputs_ids, position_ids, prompt_mask, input_prep_mode: Optional[str] = None):
        input_prep_mode = input_prep_mode or self.input_prep_mode
        if input_prep_mode == "bd_packed":
            return self._prepare_for_bd_training_result(inputs_ids, position_ids, prompt_mask)
        if input_prep_mode == "infer_matched":
            return self._prepare_for_infer_matched_training_result(inputs_ids, position_ids, prompt_mask)
        raise ValueError(
            f"Unknown input_prep_mode '{input_prep_mode}'. "
            f"Supported: {sorted(TRAINING_INPUT_PREP_MODES)}"
        )

    def _zero_loss_connected(self, ref: Optional[torch.Tensor] = None) -> torch.Tensor:
        """Return a scalar 0.0 loss that is connected to the autograd graph via
        EVERY trainable MRP parameter.

        Why: when one rank hits this path (its supervised set is empty for the
        current batch) and another rank doesn't, the empty rank's backward
        must still emit a grad for every parameter the non-empty rank emits a
        grad for. Otherwise DDP/ZeRO sees asymmetric gradient bucket flushes
        — the empty rank fires a tiny allreduce on a single LayerNorm
        (NumelIn=hidden_dim) while the other rank fires the full MRP bucket
        — and NCCL times out at the 600 s watchdog. Touching every trainable
        MRP param with a 0·p.sum() term keeps the backward graph rank-symmetric.

        Falling back to ``ref.sum() * 0.0`` doesn't work when ``ref`` comes from
        a frozen backbone (``freeze_backbone=True``): ``requires_grad=False``
        raises "element 0 of tensors does not require grad".
        """
        zero = torch.zeros((), device=self.device)
        any_trainable = False
        for p in self.mrp_modules.parameters():
            if p.requires_grad:
                zero = zero + p.sum() * 0.0
                any_trainable = True
        if any_trainable:
            return zero
        # No trainable MRP param found; fall back to ref (may still be detached,
        # but nothing is trainable anyway).
        if ref is not None and ref.requires_grad:
            return ref.sum() * 0.0
        return torch.zeros((), device=self.device)

    def _compute_loss_and_metrics(
        self,
        hidden_states: torch.Tensor,
        labels: torch.LongTensor,
        p_mask: torch.Tensor,
        answer_len: int,
        target_hidden_states: Optional[torch.Tensor],
        denoised_target_hidden_states: Optional[torch.Tensor],
    ) -> torch.Tensor:
        """Compute training loss (and optionally profile metrics) from MRP hidden states."""
        if hidden_states.shape[0] == 0 or answer_len == 0:
            return self._zero_loss_connected(hidden_states)
        loss = self.loss_fn.compute(
            hidden_states=hidden_states,
            labels=labels,
            lm_head=self.lm_head,
            p_mask=p_mask,
            answer_len=answer_len,
            target_hidden_states=target_hidden_states,
            denoised_target_hidden_states=denoised_target_hidden_states,
        )
        if self._profile_mrp_metrics:
            self._mrp_step_metrics = compute_mrp_profile_metrics(
                hidden_states=hidden_states,
                labels=labels,
                lm_head=self.lm_head,
                p_mask=p_mask,
                answer_len=answer_len,
                target_hidden_states=target_hidden_states,
                denoised_target_hidden_states=denoised_target_hidden_states,
                is_sum_loss=self.loss_fn.is_sum_loss,
            )
        return loss

    def _mrp_step_weights(self, K: int) -> List[float]:
        """Per-step loss weights for K-step training (``mrp_steps >= 2``)."""
        if self.loss_weight_mode == "uniform":
            return [1.0 / K] * K
        raise ValueError(f"unknown loss_weight_mode: {self.loss_weight_mode!r}")

    def _reveal_one_step_inplace(
        self,
        *,
        concat_inputs_ids: torch.LongTensor,
        logits_to_keep: torch.BoolTensor,
        pos_to_keep: torch.BoolTensor,
        inv: torch.LongTensor,
        labels_full: torch.LongTensor,
        unique_block_ids: torch.LongTensor,
        n_unique_blocks: int,
        B: int,
        concat_len: int,
    ) -> torch.Tensor:
        """Perform a single reveal round per ``self.reveal_mode`` ('gt' or
        'gt_random'). Mutates ``concat_inputs_ids``, ``logits_to_keep``,
        ``pos_to_keep`` in place. Returns a 1D LongTensor of flat indices (into
        the supervised set) revealed in this step."""
        device = concat_inputs_ids.device
        revealed_parts: List[torch.Tensor] = []

        # gt / gt_random: rounds of per-block amax over uniform random scores.
        if self.reveal_mode == "gt_random":
            _choices = torch.tensor(
                self.gt_random_topk, device=device, dtype=torch.long,
            )
            _choice_idx = torch.randint(
                0, _choices.numel(), (B, n_unique_blocks), device=device,
            )
            _gt_random_budget = _choices[_choice_idx]
            _gt_random_budget_expanded = torch.gather(
                _gt_random_budget, 1, unique_block_ids
            )
            _n_per_block = int(max(self.gt_random_topk))
        else:  # "gt"
            _n_per_block = self.gt_topk
            _gt_random_budget_expanded = None

        for _topk_iter in range(_n_per_block):
            if not logits_to_keep.any():
                break
            if _gt_random_budget_expanded is not None:
                _eligible_keep = logits_to_keep & (
                    _gt_random_budget_expanded > _topk_iter
                )
            else:
                _eligible_keep = logits_to_keep
            if not _eligible_keep.any():
                break

            _pos_scores = torch.rand(B, concat_len, device=device)
            _rand_scores = torch.where(
                _eligible_keep, _pos_scores,
                torch.full((B, concat_len), float("-inf"), device=device),
            )
            _rev_b_parts = []
            _rev_pos_parts = []
            for _b in range(B):
                _active_block_ids = torch.unique(
                    unique_block_ids[_b][_eligible_keep[_b]]
                )
                for _block_id in _active_block_ids:
                    _block_mask = (
                        _eligible_keep[_b] & (unique_block_ids[_b] == _block_id)
                    )
                    if not _block_mask.any():
                        continue
                    _rev_pos = torch.argmax(torch.where(
                        _block_mask,
                        _rand_scores[_b],
                        torch.full_like(_rand_scores[_b], float("-inf")),
                    ))
                    _rev_b_parts.append(torch.as_tensor(_b, device=device))
                    _rev_pos_parts.append(_rev_pos)
            if not _rev_b_parts:
                break
            _rev_b = torch.stack(_rev_b_parts)
            _rev_pos = torch.stack(_rev_pos_parts)
            _rev_ks = inv[_rev_b, _rev_pos]
            concat_inputs_ids[_rev_b, _rev_pos] = labels_full[_rev_ks]
            logits_to_keep[_rev_b, _rev_pos] = False
            pos_to_keep[_rev_ks] = False
            revealed_parts.append(_rev_ks)

        return (torch.cat(revealed_parts) if revealed_parts
                else torch.empty(0, dtype=torch.long, device=device))

    def _run_multi_step_mrp_training(
        self,
        *,
        concat_inputs_ids: torch.LongTensor,
        concat_position_ids: torch.LongTensor,
        flex_attention_mask_3d,
        attention_mask_dense: Optional[torch.Tensor],
        cache_position,
        logits_to_keep: torch.BoolTensor,
        pos_to_keep: torch.BoolTensor,
        inv: torch.LongTensor,
        labels: torch.LongTensor,
        p_mask: torch.Tensor,
        answer_len,
        target_h_A: torch.Tensor,
        mrp_anchor: Optional[torch.Tensor] = None,
        unique_block_ids: torch.LongTensor,
        n_unique_blocks: int,
        B: int,
        concat_len: int,
        output_attentions: Optional[bool],
        output_hidden_states: Optional[bool],
        **kwargs,
    ) -> torch.Tensor:
        """K-step MRP training. See `set_mrp_steps`.

        Algorithm (K = ``self.mrp_steps``):

            acc_0 = h_A = target_h_A
            For k = 1..K:
                reveal one round on concat_inputs_ids -> M_k
                M_k -> tgt (no_grad) -> h_T_k
                h_p_k = MRP(inputs_embeds=acc_{k-1}, input_ids=M_k)
                L_k   = loss_fn(h_p_k, target=acc_{k-1}, denoised_target=h_T_k,
                                labels_k, p_mask_k, answer_len_k)
                acc_k = acc_{k-1} + h_p_k
            Loss = Σ w_k · L_k

        Mutates concat_inputs_ids / logits_to_keep / pos_to_keep in place.
        Returns the scalar combined loss and populates self._mrp_step_metrics
        (per-step entries) when profiling is enabled.
        """
        K = int(self.mrp_steps)
        assert K >= 2, "multi-step path requires mrp_steps >= 2"

        labels_full = labels
        p_mask_full = p_mask
        answer_len_full = answer_len

        # Sum losses (e.g. ce_sum, kd_diff_sum) train h_p_k as a residual on top
        # of the accumulator acc_{k-1} = h_A + Σ_{i<k} h_p_i and are paired with
        # the `logits_sum` inference mode (which feeds the same accumulator).
        # Non-sum losses (ce, kd, kd_diff, l1, mse) supervise lm_head(h_p_k)
        # directly and are paired with the `none` inference mode, which feeds
        # the previous MRP hidden h_p_{k-1} (not the accumulator) at iter ≥ 1.
        # Match that pairing here so training and inference see the same input
        # distribution at each k. See generate() for the inference side.
        is_sum_loss = bool(getattr(self.loss_fn, "is_sum_loss", False))
        needs_denoised = bool(getattr(self.loss_fn, "needs_denoised_target", False))

        # ── Pre-pass: execute K reveals up-front, snapshotting the per-step
        # state we need (post-reveal concat_inputs_ids, the supervised mask,
        # and per-step label/p_mask/answer_len) so we can run all K target
        # backbone forwards as one batched call. Reveals don't depend on the
        # MRP head's output (they read only labels/random scores, or
        # _conf_tokens/_conf_scores precomputed once from target_h_A above),
        # so doing them ahead of the MRP loop is semantically identical to
        # the per-step interleaved version.
        snapshots: List[dict] = []
        for k in range(1, K + 1):
            if not logits_to_keep.any():
                break
            revealed_ks = self._reveal_one_step_inplace(
                concat_inputs_ids=concat_inputs_ids,
                logits_to_keep=logits_to_keep,
                pos_to_keep=pos_to_keep,
                inv=inv,
                labels_full=labels_full,
                unique_block_ids=unique_block_ids,
                n_unique_blocks=n_unique_blocks,
                B=B, concat_len=concat_len,
            )
            if revealed_ks.numel() == 0:
                break
            # Need at least one still-masked position at end of step.
            if not pos_to_keep.any():
                break
            sup_mask, labels_k, p_mask_k, answer_len_k = self._build_step_supervision(
                sup_mask_end=logits_to_keep,
                pos_to_keep_end=pos_to_keep,
                labels_full=labels_full,
                p_mask_full=p_mask_full,
                answer_len_full=answer_len_full,
            )
            snapshots.append(dict(
                cids=concat_inputs_ids.clone(),
                sup_mask=sup_mask.clone(),
                labels_k=labels_k,
                p_mask_k=p_mask_k,
                answer_len_k=answer_len_k,
                n_revealed=int(revealed_ks.numel()),
                n_after_reveal=int(pos_to_keep.sum().item()),
            ))

        # Synchronize K_eff across ranks. The snapshot loop breaks on
        # data-dependent conditions (logits_to_keep.any() / revealed_ks /
        # pos_to_keep), so different ranks can land on different K_eff. Each
        # snapshot drives one grad-carrying MRP backbone forward below, so a
        # rank skew here translates to a different number of grad buckets per
        # rank and a NCCL ALLREDUCE size mismatch on the next step (observed
        # as Rank0 NumelIn=2560 vs Rank1 NumelIn=~315M, timing out at 600s).
        # Take the rank-min so every rank runs the same number of MRP forwards.
        K_eff = len(snapshots)
        if torch.distributed.is_available() and torch.distributed.is_initialized():
            _k_t = torch.tensor(K_eff, device=target_h_A.device, dtype=torch.long)
            torch.distributed.all_reduce(_k_t, op=torch.distributed.ReduceOp.MIN)
            K_eff = int(_k_t.item())
            snapshots = snapshots[:K_eff]

        if not snapshots:
            return self._zero_loss_connected(target_h_A)

        # ── Batched target forward: stack the K post-reveal concat_inputs_ids
        # along the batch dim and run one no_grad backbone pass. The attention
        # pattern is identical for every step (block structure depends on
        # position_ids, not token IDs), so we tile the dense mask K_eff times
        # and rebuild a single BlockMask. Skipped entirely when the loss
        # doesn't read the denoised target.
        h_T_per_step: List[Optional[torch.Tensor]] = [None] * K_eff
        if needs_denoised:
            stacked_cids = torch.cat([s["cids"] for s in snapshots], dim=0)
            stacked_pos = concat_position_ids.repeat(K_eff, 1)
            if attention_mask_dense is not None:
                stacked_dense = attention_mask_dense.repeat(K_eff, 1, 1)
                stacked_attn = create_flex_attention_mask(stacked_dense)
            else:
                stacked_attn = flex_attention_mask_3d  # caller didn't supply dense; assume mask is reusable
            with torch.no_grad():
                h_T_all_out: BaseModelOutputWithPast = self.model(
                    input_ids=stacked_cids,
                    attention_mask=stacked_attn,
                    position_ids=stacked_pos,
                    past_key_values=None,
                    inputs_embeds=None,
                    output_attentions=False,
                    output_hidden_states=False,
                    cache_position=cache_position,
                )
            h_T_all = h_T_all_out.last_hidden_state  # (K_eff*B, L, D)
            h_T_per_step = list(torch.chunk(h_T_all, K_eff, dim=0))

        # ── Sequential MRP forwards (cannot be batched: step k input depends
        # on h_p_{k-1} via hidden_acc / prev_h).
        # Layer fusion swaps the chain seed from h_A to the fused projection P.
        # target_h_A is kept untouched for loss-comparison targets below.
        anchor_seed = mrp_anchor if mrp_anchor is not None else target_h_A
        hidden_acc = anchor_seed  # seeds the chain (grad-carrying)
        prev_h = anchor_seed      # for non-sum losses: chain over h_p_{k-1}
        step_losses: List[torch.Tensor] = []
        step_metrics: dict = {}
        for k_idx, snap in enumerate(snapshots, start=1):
            cids_k = snap["cids"]
            sup_mask = snap["sup_mask"]

            mrp_inputs_embeds = hidden_acc if is_sum_loss else prev_h
            mrp_out = self.mrp_modules[0].model(
                embed_tokens=self.model.embed_tokens,
                input_ids=cids_k,
                inputs_embeds=mrp_inputs_embeds,
                attention_mask=flex_attention_mask_3d,
                position_ids=concat_position_ids,
                output_attentions=output_attentions,
                output_hidden_states=output_hidden_states,
                return_dict=True,
                cache_position=cache_position,
                **kwargs,
            )
            h_p_k = mrp_out.last_hidden_state

            h_p_k_sub = h_p_k[sup_mask].contiguous()
            acc_sub = hidden_acc[sup_mask].contiguous().detach()
            h_T_k = h_T_per_step[k_idx - 1]
            h_T_k_sub = (
                h_T_k[sup_mask].contiguous().detach() if h_T_k is not None else None
            )

            p_mask_eff = snap["p_mask_k"]

            L_k = self._compute_loss_and_metrics(
                hidden_states=h_p_k_sub,
                labels=snap["labels_k"],
                p_mask=p_mask_eff,
                answer_len=snap["answer_len_k"],
                target_hidden_states=acc_sub,
                denoised_target_hidden_states=h_T_k_sub,
            )
            step_losses.append(L_k)

            if self._profile_mrp_metrics:
                step_metrics[f"mrp/loss_step_{k_idx}"] = float(L_k.detach().item())
                step_metrics[f"mrp/n_revealed_step_{k_idx}"] = float(snap["n_revealed"])
                step_metrics[f"mrp/n_after_reveal_step_{k_idx}"] = float(snap["n_after_reveal"])

            if is_sum_loss:
                hidden_acc = hidden_acc + h_p_k
            else:
                prev_h = h_p_k

        if not step_losses:
            return self._zero_loss_connected(target_h_A)

        weights = self._mrp_step_weights(len(step_losses))
        total_loss = weights[0] * step_losses[0]
        for w, L in zip(weights[1:], step_losses[1:]):
            total_loss = total_loss + w * L

        if self._profile_mrp_metrics and self._mrp_step_metrics is not None:
            self._mrp_step_metrics.update(step_metrics)
            self._mrp_step_metrics["mrp/loss"] = float(total_loss.detach().item())
            self._mrp_step_metrics["mrp/n_steps"] = float(len(step_losses))
        return total_loss

    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        logits_to_keep: Union[int, torch.Tensor] = 0,
        use_mrp: bool = True,
        **kwargs: Unpack[KwargsForCausalLM],
    ) -> CausalLMOutputWithPast:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.

        Example:

        ```python
        >>> from transformers import AutoTokenizer, SDARForCausalLM

        >>> model = SDARForCausalLM.from_pretrained("DiffuOpen/SDAR-1.7B-Chat")
        >>> tokenizer = AutoTokenizer.from_pretrained("DiffuOpen/SDAR-1.7B-Chat")

        >>> prompt = "Hey, are you conscious? Can you talk to me?"
        >>> inputs = tokenizer(prompt, return_tensors="pt")

        >>> # Generate
        >>> generate_ids = model.generate(inputs.input_ids, max_length=30)
        >>> tokenizer.batch_decode(generate_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        "Hey, are you conscious? Can you talk to me?\nI'm not conscious, but I can talk to you."
        ```"""
        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        if self.training:
            # === Precomputed path: skip target forward, use cached hidden states ===
            cached_target = kwargs.pop("cached_target_hidden_states", None)
            if cached_target is not None:
                concat_inputs_ids = kwargs.pop("cached_concat_inputs_ids")
                concat_position_ids = kwargs.pop("cached_concat_position_ids")
                original_position_ids = kwargs.pop("cached_original_position_ids")
                logits_to_keep = kwargs.pop("cached_logits_to_keep")
                logits_to_keep_half = kwargs.pop("cached_logits_to_keep_half")
                p_mask = kwargs.pop("cached_p_mask")
                labels = kwargs.pop("cached_labels")
                answer_len = kwargs.pop("cached_answer_len")
                block_size = kwargs.pop("cached_block_size")
                cached_input_prep_mode = kwargs.pop("cached_input_prep_mode", "bd_packed")
                denoised_target_hidden_states = kwargs.pop("cached_denoised_hidden_states", None)

                # Reconstruct the mode-specific training attention mask from position_ids.
                _, _, flex_attention_mask_3d = self._build_training_attention_masks(
                    original_position_ids.to(concat_inputs_ids.device),
                    input_prep_mode=cached_input_prep_mode,
                    block_size=block_size,
                )

                target_hidden_states_for_kd = cached_target

                # MRP module forward (skip target model entirely)
                outputs = self.mrp_modules[0].model(
                    embed_tokens=self.model.embed_tokens,
                    input_ids=concat_inputs_ids,
                    inputs_embeds=cached_target,
                    attention_mask=flex_attention_mask_3d,
                    position_ids=concat_position_ids,
                    output_attentions=output_attentions,
                    output_hidden_states=output_hidden_states,
                    return_dict=True,
                    cache_position=cache_position,
                    **kwargs,
                )

                hidden_states = outputs.last_hidden_state
                hidden_states = hidden_states[logits_to_keep].contiguous()
                if target_hidden_states_for_kd is not None:
                    target_hidden_states_for_kd = target_hidden_states_for_kd[logits_to_keep].contiguous().detach()
                if denoised_target_hidden_states is not None:
                    denoised_target_hidden_states = denoised_target_hidden_states[logits_to_keep].contiguous().detach()

                loss = self._compute_loss_and_metrics(
                    hidden_states=hidden_states,
                    labels=labels,
                    p_mask=p_mask,
                    answer_len=answer_len,
                    target_hidden_states=target_hidden_states_for_kd,
                    denoised_target_hidden_states=denoised_target_hidden_states,
                )
                logits = None

            # === Original path: run target forward + MRP ===
            else:
                assert inputs_embeds is None, "only support input_ids during training"
                prompt_mask = (labels == -100) if labels is not None else None
                assert labels is not None, "Labels must be provided for training."
                answer_len = (~prompt_mask).sum()

                position_ids = modify_padded_position_ids_2d(position_ids)
                prep = self.prepare_training_inputs(input_ids, position_ids, prompt_mask)
                concat_inputs_ids = prep.input_ids
                concat_position_ids = prep.position_ids
                flex_attention_mask_3d = prep.attention_mask
                logits_to_keep_half = prep.logits_to_keep_half
                logits_to_keep = prep.logits_to_keep
                p_mask = prep.p_mask
                outputs: BaseModelOutputWithPast = self.model(
                    input_ids=concat_inputs_ids,
                    attention_mask=flex_attention_mask_3d,
                    position_ids=concat_position_ids,
                    past_key_values=past_key_values,
                    inputs_embeds=inputs_embeds,
                    output_attentions=output_attentions,
                    output_hidden_states=output_hidden_states,
                    cache_position=cache_position,
                    **kwargs,
                )

                labels = labels[logits_to_keep_half].contiguous()
                _multi_step_done = False    # set True when mrp_steps>=2 path handles loss end-to-end
                if use_mrp:
                    # Reveal a subset of still-masked tokens into input_ids before
                    # calling MRP, keeping inputs_embeds from the original
                    # (un-denoised) target pass. This is what advances B one
                    # denoising step ahead of A.
                    assert (logits_to_keep == (concat_inputs_ids == self.config.mask_token_id)).all(), \
                        "logits_to_keep and concat_inputs_ids should be the same in mask positions, and equal to mask_token_id"

                    b_idx = torch.arange(concat_inputs_ids.shape[0], device=concat_inputs_ids.device)

                    # Build inv once: maps (batch, seq_pos) -> flat index in the supervised set.
                    # We keep it fixed so each iteration can look up the right flat index.
                    kept_pos = logits_to_keep.nonzero(as_tuple=False)
                    inv = torch.full_like(logits_to_keep, -1, dtype=torch.long)
                    inv[kept_pos[:, 0], kept_pos[:, 1]] = torch.arange(kept_pos.size(0), device=kept_pos.device)

                    pos_to_keep = torch.ones(p_mask.shape[0], dtype=torch.bool, device=logits_to_keep.device)
                    _labels_full_k1 = labels
                    _p_mask_full_k1 = p_mask
                    _answer_len_full_k1 = answer_len

                    # --- Per-block reveal pre-computation ---
                    # Assign each position a unique block ID so positions in the same noisy
                    # block share the same ID. Bidirectional attention is per-block, so reveals
                    # must be too — a global argmax would spread reveals across independent blocks
                    # and leave 95%+ of supervised tokens with zero contextual change.
                    # Block ID = sample_idx_in_pack * max_blocks_per_sample + pos_within_sample // block_size
                    # Sample boundaries are detected where concat_position_ids drops back to 0.
                    _B, _concat_len = concat_inputs_ids.shape
                    _block_size = self.config.block_size
                    _pos_ids = concat_position_ids                                           # [B, concat_len]
                    _is_new_sample = torch.zeros(_B, _concat_len, dtype=torch.bool, device=concat_inputs_ids.device)
                    _is_new_sample[:, 0] = True
                    _is_new_sample[:, 1:] = _pos_ids[:, 1:] < _pos_ids[:, :-1]             # drop = new sample
                    _sample_ids = _is_new_sample.long().cumsum(dim=1) - 1                   # [B, concat_len]
                    _max_blocks = (_concat_len + _block_size - 1) // _block_size            # safe upper bound
                    _unique_block_ids = _sample_ids * _max_blocks + _pos_ids // _block_size  # [B, concat_len]
                    _n_unique_blocks = int(_unique_block_ids.max().item()) + 1
                    # --- End pre-computation ---

                    # Reveal tokens per block, per reveal_mode:
                    #   "gt":        ``gt_topk`` random positions per block, each
                    #                filled with the ground-truth label.
                    #   "gt_random": sample one count from ``gt_random_topk`` per
                    #                active block, then reveal that many random
                    #                ground-truth positions.
                    if self.mrp_steps >= 2:
                        # Multi-step (K>=2) MRP training: chain K reveals + K MRP
                        # forwards with a hidden accumulator. See
                        # `_run_multi_step_mrp_training`.
                        loss = self._run_multi_step_mrp_training(
                            concat_inputs_ids=concat_inputs_ids,
                            concat_position_ids=concat_position_ids,
                            flex_attention_mask_3d=flex_attention_mask_3d,
                            attention_mask_dense=prep.attention_mask_dense,
                            cache_position=cache_position,
                            logits_to_keep=logits_to_keep,
                            pos_to_keep=pos_to_keep,
                            inv=inv,
                            labels=labels,
                            p_mask=p_mask,
                            answer_len=answer_len,
                            target_h_A=outputs.last_hidden_state,
                            mrp_anchor=self._mrp_anchor(outputs),
                            unique_block_ids=_unique_block_ids,
                            n_unique_blocks=_n_unique_blocks,
                            B=_B,
                            concat_len=_concat_len,
                            output_attentions=output_attentions,
                            output_hidden_states=output_hidden_states,
                            **kwargs,
                        )
                        _multi_step_done = True
                    else:
                        # "gt" / "gt_random": reveal positions via rounds of
                        # per-block amax over uniform random scores. gt_random
                        # samples a per-block budget before the loop; blocks whose
                        # budget is exhausted are skipped in later rounds.
                        if self.reveal_mode == "gt_random":
                            _choices = torch.tensor(
                                self.gt_random_topk,
                                device=concat_inputs_ids.device,
                                dtype=torch.long,
                            )
                            _choice_idx = torch.randint(
                                0,
                                _choices.numel(),
                                (_B, _n_unique_blocks),
                                device=concat_inputs_ids.device,
                            )
                            _gt_random_budget = _choices[_choice_idx]
                            _gt_random_budget_expanded = torch.gather(
                                _gt_random_budget, 1, _unique_block_ids
                            )
                            _n_per_block = int(max(self.gt_random_topk))
                        else:  # "gt"
                            _n_per_block = self.gt_topk
                            _gt_random_budget_expanded = None

                        for _topk_iter in range(_n_per_block):
                            if not logits_to_keep.any():
                                break

                            if _gt_random_budget_expanded is not None:
                                _eligible_keep = logits_to_keep & (
                                    _gt_random_budget_expanded > _topk_iter
                                )
                            else:
                                _eligible_keep = logits_to_keep
                            if not _eligible_keep.any():
                                break

                            # Fresh uniform random score per still-masked position;
                            # -inf elsewhere. Already-revealed positions are masked
                            # via logits_to_keep, so later rounds pick the next
                            # unrevealed position.
                            _pos_scores = torch.rand(
                                _B, _concat_len, device=concat_inputs_ids.device
                            )
                            _rand_scores = torch.where(
                                _eligible_keep,
                                _pos_scores,
                                torch.full((_B, _concat_len), float("-inf"),
                                           device=concat_inputs_ids.device),
                            )

                            _rev_b_parts = []
                            _rev_pos_parts = []
                            for _b in range(_B):
                                _active_block_ids = torch.unique(
                                    _unique_block_ids[_b][_eligible_keep[_b]]
                                )
                                for _block_id in _active_block_ids:
                                    _block_mask = (
                                        _eligible_keep[_b]
                                        & (_unique_block_ids[_b] == _block_id)
                                    )
                                    if not _block_mask.any():
                                        continue
                                    _rev_pos = torch.argmax(torch.where(
                                        _block_mask,
                                        _rand_scores[_b],
                                        torch.full_like(_rand_scores[_b], float("-inf")),
                                    ))
                                    _rev_b_parts.append(
                                        torch.as_tensor(_b, device=concat_inputs_ids.device)
                                    )
                                    _rev_pos_parts.append(_rev_pos)

                            if not _rev_b_parts:
                                break  # all blocks exhausted
                            _rev_b = torch.stack(_rev_b_parts)
                            _rev_pos = torch.stack(_rev_pos_parts)
                            _rev_ks = inv[_rev_b, _rev_pos]
                            assert (_rev_ks >= 0).all(), \
                                "inv lookup returned -1 for a selected reveal position"
                            concat_inputs_ids[_rev_b, _rev_pos] = labels[_rev_ks]
                            logits_to_keep[_rev_b, _rev_pos] = False
                            pos_to_keep[_rev_ks] = False
                    if not _multi_step_done:
                        n_before_reveal = int(pos_to_keep.shape[0])
                        n_revealed = int((~pos_to_keep).sum().item())
                        n_after_reveal = int(pos_to_keep.sum().item())

                        # Supervise only the still-masked positions at end of
                        # step. The answer_len correction subtracts 1/p_mask for
                        # the revealed positions, keeping the diffusion CE
                        # estimator properly calibrated.
                        _sup_mask_step, labels, p_mask, answer_len = self._build_step_supervision(
                            sup_mask_end=logits_to_keep,
                            pos_to_keep_end=pos_to_keep,
                            labels_full=_labels_full_k1,
                            p_mask_full=_p_mask_full_k1,
                            answer_len_full=_answer_len_full_k1,
                        )
                        # Mirror the chosen supervision set into ``logits_to_keep``
                        # because downstream slicing uses it to gather MRP /
                        # target / denoised hidden states.
                        logits_to_keep = _sup_mask_step

                        # Save target hidden states (from the un-denoised pass) for potential KD loss
                        target_hidden_states_for_kd = outputs.last_hidden_state

                        # Second target forward on denoised input (for kd_diff / kd_diff_mix losses,
                        # or when profiling is enabled to compute ||B-A|| metrics).
                        denoised_target_hidden_states = None
                        _needs_denoised_k1 = (
                            getattr(self.loss_fn, 'needs_denoised_target', False)
                            or self._profile_mrp_metrics
                        )
                        if _needs_denoised_k1:
                            with torch.no_grad():
                                denoised_outputs: BaseModelOutputWithPast = self.model(
                                    input_ids=concat_inputs_ids,
                                    attention_mask=flex_attention_mask_3d,
                                    position_ids=concat_position_ids,
                                    past_key_values=None,
                                    inputs_embeds=None,
                                    output_attentions=False,
                                    output_hidden_states=False,
                                    cache_position=cache_position,
                                )
                                denoised_target_hidden_states = denoised_outputs.last_hidden_state

                        concat_inputs_embeds = self._mrp_anchor(outputs)
                        outputs = self.mrp_modules[0].model(
                            embed_tokens=self.model.embed_tokens,
                            input_ids=concat_inputs_ids,
                            inputs_embeds=concat_inputs_embeds,
                            attention_mask=flex_attention_mask_3d,
                            position_ids=concat_position_ids,
                            output_attentions=output_attentions,
                            output_hidden_states=output_hidden_states,
                            return_dict=True,
                            cache_position=cache_position,
                            **kwargs,
                        )
                else:
                    target_hidden_states_for_kd = None
                    denoised_target_hidden_states = None
                if not _multi_step_done:
                    hidden_states = outputs.last_hidden_state
                    hidden_states = hidden_states[logits_to_keep].contiguous()
                    # Extract matching target/denoised hidden states for KD loss
                    if target_hidden_states_for_kd is not None:
                        target_hidden_states_for_kd = target_hidden_states_for_kd[logits_to_keep].contiguous().detach()
                    if denoised_target_hidden_states is not None:
                        denoised_target_hidden_states = denoised_target_hidden_states[logits_to_keep].contiguous().detach()

                    loss = self._compute_loss_and_metrics(
                        hidden_states=hidden_states,
                        labels=labels,
                        p_mask=p_mask,
                        answer_len=answer_len,
                        target_hidden_states=target_hidden_states_for_kd,
                        denoised_target_hidden_states=denoised_target_hidden_states,
                    )
                    if self._profile_mrp_metrics and self._mrp_step_metrics is not None:
                        # Add loss_head_0 so the trainer's avg_loss is the clean per-batch
                        # loss rather than the HF Trainer's grad-accum-inflated fallback.
                        self._mrp_step_metrics["mrp/loss_head_0"] = float(loss.item())
                        self._mrp_step_metrics["mrp/n_before_reveal"] = float(n_before_reveal)
                        self._mrp_step_metrics["mrp/n_revealed"] = float(n_revealed)
                        self._mrp_step_metrics["mrp/n_after_reveal"] = float(n_after_reveal)
                logits = None
        else:
            # decoder outputs consists of (dec_features, layer_state, dec_hidden, dec_attn)
            outputs: BaseModelOutputWithPast = self.model(
                input_ids=input_ids,
                attention_mask=attention_mask,
                position_ids=position_ids,
                past_key_values=past_key_values,
                inputs_embeds=inputs_embeds,
                output_attentions=output_attentions,
                output_hidden_states=output_hidden_states,
                cache_position=cache_position,
                **kwargs,
            )
            if use_mrp:
                inputs_embeds = self._mrp_anchor(outputs)
                outputs: BaseModelOutputWithPast = self.mrp_modules[0].model(
                    embed_tokens=self.model.embed_tokens,
                    input_ids=input_ids,
                    attention_mask=attention_mask,
                    position_ids=position_ids,
                    past_key_values=past_key_values,
                    inputs_embeds=inputs_embeds,
                    use_cache=use_cache,
                    output_attentions=output_attentions,
                    output_hidden_states=output_hidden_states,
                    cache_position=cache_position,
                    **kwargs,
                )

            hidden_states = outputs.last_hidden_state
            # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
            slice_indices = slice(-logits_to_keep,
                                None) if isinstance(logits_to_keep, int) else logits_to_keep
            hidden_states = hidden_states[:, slice_indices, :].contiguous()
            fuse_linear_and_cross_entropy = self.config.fuse_cross_entropy and self.training
            if fuse_linear_and_cross_entropy:
                # When using fused_linear_ce_loss, we do not compute the whole logits on HBM
                logits = None
            else:
                logits = self.lm_head(hidden_states)

            loss = None
            if labels is not None:
                # FusedLinearCrossEntropyLoss will be implemented by monkey patch when training
                # We don't use it when inferencing
                loss_fct = nn.CrossEntropyLoss()  # nn.CE
                loss = loss_fct(
                    logits.view(-1, self.config.vocab_size), labels.view(-1))

        return CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
        )

    def _mrp_aggregate(
        self,
        mode: str,
        mrp_logits: torch.FloatTensor,
        target_logits: torch.FloatTensor,
        prev_logits: torch.FloatTensor,
        alpha: float = 0.5,
        sum_scale: float = 1.0,
    ) -> torch.FloatTensor:
        """Pre-sampling MRP logit aggregation (MRP iterations only).

        Controls how the current MRP head's logits are combined with the
        previous iteration's logits before sampling.

        Modes:
            none        — use MRP logits unchanged.
            logits_sum  — prev_logits + sum_scale * mrp_logits (accumulates
                          across iters; sum_scale defaults to 1.0).
        """
        if mode == 'none':
            return mrp_logits
        elif mode == 'logits_sum':
            # sum_scale amplifies the per-iter correction term. scale=1.0
            # reproduces the original A + C accumulator; scale=2.0 gives A + 2C.
            return prev_logits + sum_scale * mrp_logits
        else:
            valid = ['none', 'logits_sum']
            raise ValueError(
                f"Unknown mrp_logit_mix_mode: '{mode}'. Valid modes: {valid}"
            )

    @torch.no_grad()
    def generate(
        self,
        input_ids,
        mask_id=None,
        attention_mask=None,
        pad_token_id=None,
        use_cache=True,
        do_sample=True,
        max_length=128,
        block_length=8,
        denoising_steps=8,
        temperature=1.0,
        top_k=0,
        top_p=1.0,
        remasking_strategy='low_confidence_static', # although low conf dynamic is the standard way, we use low conf static as default for simplicity.
        confidence_threshold=0.85,
        eb_threshold=None,
        stopping_criteria=None,
        stopping_criteria_idx=None,
        use_mrp=True,
        mrp_steps=0,
        verbose=False,
        **mrp_kwargs,
    ):
        # MRP-related options are passed via **mrp_kwargs and extracted here
        # so that new options can be added without churning the signature or
        # every caller. `use_mrp` and `mrp_steps` stay explicit because they
        # gate the whole MRP path.
        # Pre-sampling MRP logit aggregation (orthogonal to mrp_verify_mode).
        # One of: 'none', 'logits_sum'.
        mrp_logit_mix_mode = mrp_kwargs.get('mrp_logit_mix_mode', 'none')
        # Inference mode selector. One of:
        #   'none'            — direct MRP decoding after the target step.
        #   'spec'            — vanilla within-block speculative decoding.
        #   'residual_remask' — aggressive target unmask + MRP residual veto.
        mrp_verify_mode = mrp_kwargs.get('mrp_verify_mode', 'none')
        # Per-token veto threshold for mrp_verify_mode == 'residual_remask'.
        # The target unmasks aggressively (low confidence_threshold); a
        # committed token is remasked when |C[pos, committed_id]| > this delta,
        # where C is MRP's raw logit-space residual (its prediction). Larger
        # delta => looser veto (fewer remasks). Default 1.0; tune later.
        residual_delta = float(mrp_kwargs.get('residual_delta', 1.0))
        # Per-iter correction scale for mrp_logit_mix_mode == 'logits_sum'.
        # Multiplies both the per-iter MRP logits term in the accumulator AND
        # the per-iter MRP hidden state fed to the next MRP forward, so the
        # logits and the inputs_embeds stay consistent. Defaults to 1.0
        # (original A+C behavior); set to 2.0 for A+2C, etc. Ignored by
        # mix modes other than 'logits_sum'.
        mrp_logit_sum_scale = float(mrp_kwargs.get('mrp_logit_sum_scale', 1.0))
        # MRP iters (iter >= 1) use their own remasking strategy and per-iter
        # transfer count, independent of the target's (iter 0). Defaults match
        # the intended fast-MRP config: low_confidence_static with 1 token
        # committed per MRP iter. To have MRP inherit target behavior, pass
        # mrp_remasking_strategy=remasking_strategy explicitly.
        mrp_remasking_strategy = mrp_kwargs.get('mrp_remasking_strategy', 'low_confidence_static')
        mrp_num_transfer_per_iter = mrp_kwargs.get('mrp_num_transfer_per_iter', 1)

        if not use_cache:
            logger.warning_once("Generation without cache is not supported.")
        
        if attention_mask is not None:
            logger.warning_once("The provided attention_mask will be ignored for attention during generation, but it will be used to infer prompt lengths for batched inputs.")
            
        if do_sample == False:
            logger.warning_once("Setting `do_sample=False` is not supported, as the generation process relies on sampling to perform the progressive denoising. Setting `do_sample=True`.")
            
        if pad_token_id is not None:
            logger.warning_once("The provided `pad_token_id` will be ignored during generation, as the model uses `mask_token_id` for padding during generation.")

        assert (stopping_criteria is None) or (stopping_criteria_idx is None), "Only one of `stopping_criteria` and `stopping_criteria_idx` can be provided to avoid ambiguity. Please provide either a stopping criteria function or a list of token ids to stop at, but not both."

        if mrp_steps > 0:
            assert use_mrp == False
            # assert denoising_steps == block_length

        if mrp_steps == 0 and (
            mrp_verify_mode not in ('none', 'spec', 'residual_remask') or mrp_logit_mix_mode != 'none'
        ):
            logger.warning_once(
                "MRP logit aggregation / verification is configured but "
                "`mrp_steps` is 0 — it will have no effect."
            )

        # Residual-remask path: target unmasks aggressively under a low
        # confidence threshold, then MRP's logit-space residual vetoes the
        # unstable commits per token. MRP never commits — it only remasks.
        # Dispatched here (like spec) so the standard loop stays untouched.
        if mrp_verify_mode == 'residual_remask' and mrp_steps > 0:
            return self._generate_residual_remask(
                input_ids=input_ids,
                mask_id=mask_id,
                attention_mask=attention_mask,
                max_length=max_length,
                block_length=block_length,
                denoising_steps=denoising_steps,
                temperature=temperature,
                top_k=top_k,
                top_p=top_p,
                confidence_threshold=confidence_threshold,
                residual_delta=residual_delta,
                stopping_criteria=stopping_criteria,
                stopping_criteria_idx=stopping_criteria_idx,
                verbose=verbose,
            )

        # Vanilla speculative-decoding path: dispatch BEFORE the standard
        # per-block loop. K = mrp_steps (0 => no-op, identical to 'none').
        # See panel (d) of the paper figure for the verification mask layout.
        if mrp_verify_mode == 'spec' and mrp_steps > 0:
            return self._generate_spec(
                input_ids=input_ids,
                mask_id=mask_id,
                attention_mask=attention_mask,
                max_length=max_length,
                block_length=block_length,
                denoising_steps=denoising_steps,
                temperature=temperature,
                top_k=top_k,
                top_p=top_p,
                remasking_strategy=remasking_strategy,
                confidence_threshold=confidence_threshold,
                eb_threshold=eb_threshold,
                stopping_criteria=stopping_criteria,
                stopping_criteria_idx=stopping_criteria_idx,
                K=int(mrp_steps),
                mrp_logit_mix_mode=mrp_logit_mix_mode,
                mrp_logit_sum_scale=mrp_logit_sum_scale,
                verbose=verbose,
            )

        self.eval()
        mask_id = mask_id if mask_id is not None else self.config.mask_token_id
        batch_size = input_ids.shape[0]
        if attention_mask is not None:
            prompt_lengths = attention_mask.sum(dim=1).long()
            prompt_length = int(prompt_lengths.min().item())
        else:
            prompt_lengths = torch.full(
                (batch_size,),
                input_ids.shape[1],
                dtype=torch.long,
                device=input_ids.device,
            )
            prompt_length = input_ids.shape[1]
        generation_device = input_ids.device
        past_key_values = DynamicCache()

        initial_length = input_ids.shape[1]
        generation_length = max(initial_length, prompt_length + max_length)
        num_blocks = (generation_length +
                    block_length - 1) // block_length
        total_length = num_blocks * block_length

        block_mask = torch.tril(torch.ones(
            num_blocks, num_blocks, device=generation_device))
        block_diffusion_attention_mask = block_mask.repeat_interleave(block_length, dim=0)\
                                                .repeat_interleave(block_length, dim=1).unsqueeze(0)
        position_ids = torch.arange(total_length, device=generation_device).unsqueeze(0).expand(batch_size, -1)

        x = torch.full((batch_size, total_length), mask_id,
                    dtype=torch.long, device=generation_device)
        if attention_mask is not None:
            prompt_token_mask = torch.zeros((batch_size, total_length), dtype=torch.bool, device=generation_device)
            prompt_token_mask[:, :initial_length] = attention_mask.bool()
            x[:, :initial_length] = torch.where(prompt_token_mask[:, :initial_length], input_ids, x[:, :initial_length])
        else:
            x[:, :initial_length] = input_ids
        prefill_blocks = prompt_length // block_length
        prefill_length = prefill_blocks * block_length

        # ------------------------------------------------------------------
        # TPF profiling: initialize per-call counters. All bookkeeping below
        # is gated on ``profile_tpf`` so the profile-off path is unchanged.
        # ------------------------------------------------------------------
        profile_tpf = bool(getattr(self, '_profile_tpf', False))
        if profile_tpf:
            _tpf_counters = {
                # target-model forward calls, split by role
                'num_target_fwd_prefill': 0,
                'num_target_fwd_denoising': 0,
                'num_target_fwd_store_kv': 0,
                # MRP head forward calls, split by role
                'num_mrp_fwd_prefill': 0,
                'num_mrp_fwd_denoising': 0,
                'num_mrp_fwd_store_kv': 0,
                # blocks that actually ran through the denoising loop
                'num_blocks_decoded': 0,
            }
            # Per-sample token accounting (kept on CPU as int64).
            _tpf_tokens_by_target = torch.zeros(batch_size, dtype=torch.long)
            _tpf_tokens_by_mrp = torch.zeros(batch_size, dtype=torch.long)
            _tpf_mrp_tokens_proposed = torch.zeros(batch_size, dtype=torch.long)
            # Active-sample tallies captured right before each denoising target
            # forward: (~finished).sum() at that moment. Lets us see how much of
            # the batch is still productive per forward.
            _tpf_active_samples_per_fwd: List[int] = []
            # Per-iter trace: one entry per (block, step, mrp_iter) commit.
            # Each: (block_idx, step_idx, mrp_iter, is_mrp, committed_per_sample_list, active_samples).
            # Lets callers reconstruct tpf-vs-step curves per block.
            _tpf_per_iter_trace: List[dict] = []

        # Prefill stage
        if prefill_length > 0:
            cur_x = x[:, :prefill_length]
            cur_attn_mask = block_diffusion_attention_mask[:,
                                                        :prefill_length, :prefill_length]
            cur_position_ids = position_ids[:, :prefill_length]
            outputs = self(cur_x,
                attention_mask=cur_attn_mask,
                position_ids=cur_position_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=use_mrp,
                output_hidden_states=mrp_steps > 0 and not use_mrp,
            )
            if profile_tpf:
                _tpf_counters['num_target_fwd_prefill'] += 1

            if mrp_steps > 0 and not use_mrp:
                self.mrp_modules[0](
                    embed_tokens=self.model.embed_tokens,
                    lm_head=self.lm_head,
                    input_ids=cur_x,
                    inputs_embeds=self._mrp_anchor(outputs),
                    attention_mask=cur_attn_mask,
                    position_ids=cur_position_ids,
                    past_key_values=past_key_values,
                    use_cache=True,
                    store_kv=True,
                )
                if profile_tpf:
                    _tpf_counters['num_mrp_fwd_prefill'] += 1

        num_transfer_tokens = get_num_transfer_tokens(
            block_length, denoising_steps)

        # Decode stage
        block_iter = range(prefill_blocks, num_blocks)
        is_main = int(os.environ.get("LOCAL_RANK", 0)) == 0
        pbar = tqdm(block_iter, desc=f"Block {prefill_blocks}/{num_blocks}") if (verbose and is_main) else block_iter
        finished = torch.zeros(batch_size, dtype=torch.bool, device=generation_device)
        for num_block in pbar:
            cur_x = x[:, num_block*block_length:(num_block+1)*block_length].clone()
            cur_attn_mask = block_diffusion_attention_mask[
                :, num_block*block_length:(num_block+1)*block_length, :(num_block+1)*block_length
            ]
            cur_position_ids = position_ids[:, num_block *
                                            block_length:(num_block+1)*block_length]
            if profile_tpf:
                _tpf_counters['num_blocks_decoded'] += 1
            for step in range(denoising_steps):
                mask_index = (cur_x == mask_id) & (~finished.unsqueeze(1))
                if not mask_index.any():
                    break

                # print(f"block {num_block+1}/{num_blocks}, step {step}/{denoising_steps}, num_masked_tokens: {mask_index.sum().item()}")

                # Denosing
                outputs = self(cur_x,
                            attention_mask=cur_attn_mask,
                            position_ids=cur_position_ids,
                            past_key_values=past_key_values,
                            use_cache=True,
                            store_kv=False,
                            use_mrp=use_mrp,
                            output_hidden_states=mrp_steps > 0,
                        )
                if profile_tpf:
                    _tpf_counters['num_target_fwd_denoising'] += 1
                    # Active = not yet finished at the moment this forward ran.
                    _tpf_active_samples_per_fwd.append(
                        int((~finished).sum().item())
                    )
                
                target_logits = None
                prev_logits = None
                # Hidden-space accumulator for mrp_logit_mix_mode == 'logits_sum'.
                # Iter k+1's MRP should receive h_A + Σ_{i≤k} h_p_i (the B-approx),
                # not h_p_k alone — matches the A+C≈B framework that
                # kd_diff_sum / mse_sum training optimizes.
                hidden_acc = None
                for mrp_iter in range(mrp_steps + 1):
                    is_mrp_step = mrp_iter > 0

                    logits = outputs.logits.to(cur_x.device)
                    # LLaDA2.1-style: sample from the raw distribution (no
                    # mask_id suppression). This keeps x0_p honest — the prior
                    # global suppression inflated non-mask confidences at
                    # committed positions via renormalization, which made the
                    # edit gate fire on fabricated confidence. Trade-off: at
                    # mask positions the model is now free to sample mask_id
                    # if that's its top-1. Relies on the target being trained
                    # to actually predict a real token at mask positions (the
                    # denoising objective should guarantee this in practice);
                    # if a position livelocks (mask-commit keeps writing
                    # mask_id back), it'll surface as a block that never
                    # finishes, not silent corruption.

                    # Save target logits; apply pre-sampling aggregation for MRP steps
                    if not is_mrp_step:
                        target_logits = logits.detach()
                        prev_logits = logits.detach()
                    elif mrp_logit_mix_mode != 'none':
                        logits = self._mrp_aggregate(
                            mrp_logit_mix_mode, logits, target_logits, prev_logits,
                            sum_scale=mrp_logit_sum_scale,
                        )
                        prev_logits = logits.detach()

                    # Sampling
                    x0, x0_p = sample_with_temperature_topk_topp(
                        logits,
                        temperature=temperature,
                        top_k=top_k,
                        top_p=top_p
                    )

                    # Resolve the remasking strategy and per-iter transfer
                    # count for THIS iteration. Target (iter 0) uses the
                    # top-level remasking_strategy and the block's natural
                    # num_transfer_tokens[step]; MRP iters use their own
                    # strategy / per-iter count (defaulting to
                    # low_confidence_static with 1 token per MRP iter).
                    if is_mrp_step:
                        current_remasking = mrp_remasking_strategy
                        current_num_to_transfer = int(mrp_num_transfer_per_iter)
                    else:
                        current_remasking = remasking_strategy
                        current_num_to_transfer = int(num_transfer_tokens[step].item())

                    # Sampling strategy
                    if current_remasking == 'sequential':
                        transfer_index = torch.zeros_like(x0, dtype=torch.bool)
                        for j in range(cur_x.shape[0]):
                            if not mask_index[j].any():
                                continue
                            masked_positions = mask_index[j].nonzero(as_tuple=True)[0]
                            num_to_transfer = min(current_num_to_transfer, masked_positions.numel())
                            transfer_index[j, masked_positions[:num_to_transfer]] = True

                    elif current_remasking == 'low_confidence_static':
                        confidence = torch.where(mask_index, x0_p, -torch.inf)
                        transfer_index = torch.zeros_like(x0, dtype=torch.bool)
                        for j in range(confidence.shape[0]):
                            if not mask_index[j].any():
                                continue
                            num_to_transfer = min(current_num_to_transfer, int(mask_index[j].sum().item()))
                            _, idx = torch.topk(
                                confidence[j], num_to_transfer)
                            transfer_index[j, idx] = True

                    elif current_remasking == 'low_confidence_dynamic':
                        confidence = torch.where(mask_index, x0_p, -torch.inf)
                        transfer_index = torch.zeros_like(x0, dtype=torch.bool)
                        for j in range(confidence.shape[0]):
                            if not mask_index[j].any():
                                continue
                            high_conf_mask = confidence[j] > confidence_threshold
                            num_high_confidence = high_conf_mask.sum()
                            num_to_transfer = min(current_num_to_transfer, int(mask_index[j].sum().item()))
                            if num_high_confidence >= num_to_transfer:
                                transfer_index[j] = high_conf_mask
                            else:
                                _, idx = torch.topk(
                                    confidence[j], num_to_transfer)
                                transfer_index[j, idx] = True

                    elif current_remasking == "entropy_bounded":
                        eps = 1e-12
                        entropies = -(x0_p.clamp_min(eps) * (x0_p.clamp_min(eps)).log()).sum(dim=-1)
                        entropies = torch.where(mask_index, entropies, torch.inf)
                        ent_sorted, order = torch.sort(entropies, dim=1, descending=False)
                        cumsum = torch.cumsum(ent_sorted, dim=1)
                        transfer_index = torch.zeros_like(x0, dtype=torch.bool)
                        for j in range(x0_p.shape[0]):
                            if not mask_index[j].any():
                                continue
                            k = torch.searchsorted(cumsum[j], torch.tensor(eb_threshold, device=x0_p.device), right=False).item()
                            k = max(1, min(k, int(mask_index[j].sum().item())))
                            selected_token_indices = order[j, :k]
                            transfer_index[j, selected_token_indices] = True

                    else:
                        raise ValueError(
                            f"Unknown remasking strategy: {current_remasking}")

                    transfer_index[finished] = False

                    # Track MRP proposals (the full opportunity set).
                    if profile_tpf and is_mrp_step:
                        proposed_per_sample = transfer_index.sum(dim=1).detach().to('cpu', dtype=torch.long)
                        _tpf_mrp_tokens_proposed += proposed_per_sample

                    if profile_tpf:
                        # Per-sample committed count for this iteration.
                        committed_per_sample = transfer_index.sum(dim=1).detach().to('cpu', dtype=torch.long)
                        if is_mrp_step:
                            _tpf_tokens_by_mrp += committed_per_sample
                        else:
                            _tpf_tokens_by_target += committed_per_sample
                        _tpf_per_iter_trace.append({
                            'block_idx': int(num_block),
                            'step_idx': int(step),
                            'mrp_iter': int(mrp_iter),
                            'is_mrp': bool(is_mrp_step),
                            'committed_per_sample': committed_per_sample.tolist(),
                            'active_samples': int((~finished).sum().item()),
                        })

                    cur_x[transfer_index] = x0[transfer_index]

                    if mrp_iter == mrp_steps:
                        break

                    mask_index = (cur_x == mask_id) & (~finished.unsqueeze(1))
                    if not mask_index.any():
                        break

                    # At mrp_iter 0, `outputs` is the target forward: seed the
                    # anchor with h_A. Later iters carry MRP draft hidden states.
                    if mrp_iter == 0:
                        last_hidden_state = self._mrp_anchor(outputs)
                    else:
                        last_hidden_state = outputs.hidden_states[-1]
                    _need_hidden = mrp_iter < mrp_steps  # hidden states only needed if more iters follow
                    # logits_sum: feed cumulative h_A + Σ h_p to the next MRP
                    # forward. On iter 0, outputs is the target's, so
                    # last_hidden_state == h_A; seed the accumulator. On
                    # iter ≥ 1, overwrite the per-iter h_p with hidden_acc so
                    # MRP sees the approximate B from prior iters.
                    if mrp_logit_mix_mode == 'logits_sum':
                        if hidden_acc is None:
                            hidden_acc = last_hidden_state
                        else:
                            last_hidden_state = hidden_acc
                    outputs = self.mrp_modules[0](
                        embed_tokens=self.model.embed_tokens,
                        lm_head=self.lm_head,
                        input_ids=cur_x,
                        inputs_embeds=last_hidden_state,
                        attention_mask=cur_attn_mask,
                        position_ids=cur_position_ids,
                        past_key_values=past_key_values,
                        use_cache=True,
                        store_kv=False,
                        output_hidden_states=_need_hidden,
                    )
                    if profile_tpf:
                        _tpf_counters['num_mrp_fwd_denoising'] += 1
                    # Accumulate MRP hidden for the next iter under logits_sum.
                    # sum_scale mirrors the logits-side scaling so the
                    # inputs_embeds fed to MRP iter k+1 stays consistent with
                    # the logits the sampler sees.
                    if mrp_logit_mix_mode == 'logits_sum' and _need_hidden:
                        hidden_acc = hidden_acc + mrp_logit_sum_scale * outputs.hidden_states[-1]

            # Store kv cache
            outputs = self(cur_x,
                attention_mask=cur_attn_mask,
                position_ids=cur_position_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=use_mrp,
                output_hidden_states=mrp_steps > 0 and not use_mrp,
            )
            if profile_tpf:
                _tpf_counters['num_target_fwd_store_kv'] += 1

            if mrp_steps > 0 and not use_mrp:
                self.mrp_modules[0](
                    embed_tokens=self.model.embed_tokens,
                    lm_head=self.lm_head,
                    input_ids=cur_x,
                    inputs_embeds=self._mrp_anchor(outputs),
                    attention_mask=cur_attn_mask,
                    position_ids=cur_position_ids,
                    past_key_values=past_key_values,
                    use_cache=True,
                    store_kv=True,
                )
                if profile_tpf:
                    _tpf_counters['num_mrp_fwd_store_kv'] += 1

            x[:, num_block*block_length:(num_block+1)*block_length] = cur_x
            if verbose:
                pbar.set_description(f"Block {num_block + 1}/{num_blocks}")
            if stopping_criteria_idx is not None:
                token_positions = torch.arange(total_length, device=x.device).unsqueeze(0)
                generated_mask = token_positions >= prompt_lengths.unsqueeze(1)
                for stop_idx in stopping_criteria_idx:
                    finished |= ((x == stop_idx) & generated_mask).any(dim=1)
                if finished.all().item():
                    break
            if stopping_criteria is not None:
                should_stop = stopping_criteria(x, None)
                if isinstance(should_stop, torch.Tensor):
                    if should_stop.ndim == 0:
                        if should_stop.item():
                            break
                    elif should_stop.all().item():
                        break
                elif should_stop:
                    break

        if profile_tpf:
            num_target_fwd_total = (
                _tpf_counters['num_target_fwd_prefill']
                + _tpf_counters['num_target_fwd_denoising']
                + _tpf_counters['num_target_fwd_store_kv']
            )
            num_target_fwd_denoising = _tpf_counters['num_target_fwd_denoising']
            tokens_by_target = _tpf_tokens_by_target.tolist()
            tokens_by_mrp = _tpf_tokens_by_mrp.tolist()
            per_sample_tokens = [
                int(t + m) for t, m in zip(tokens_by_target, tokens_by_mrp)
            ]
            total_tokens = int(_tpf_tokens_by_target.sum().item() + _tpf_tokens_by_mrp.sum().item())
            total_tokens_by_target = int(_tpf_tokens_by_target.sum().item())
            total_tokens_by_mrp = int(_tpf_tokens_by_mrp.sum().item())
            total_mrp_tokens_proposed = int(_tpf_mrp_tokens_proposed.sum().item())
            mrp_accept_rate = (
                total_tokens_by_mrp / total_mrp_tokens_proposed
                if total_mrp_tokens_proposed > 0 else 0.0
            )
            # Denoising-only TPF: realized decoding throughput per productive
            # target forward (ignores prefill & store-KV overheads).
            tpf_denoising = (
                total_tokens / num_target_fwd_denoising
                if num_target_fwd_denoising > 0 else 0.0
            )
            tpf_end_to_end = (
                total_tokens / num_target_fwd_total
                if num_target_fwd_total > 0 else 0.0
            )
            # Ideal TPF = batch_size * (1 + mrp_steps): every sample commits
            # one target token plus one per MRP iter, on every denoising
            # forward. The gap is the batching / straggler / MRP-reject tax.
            ideal_tpf_denoising = float(batch_size * (1 + int(mrp_steps)))
            avg_active_samples_per_fwd = (
                sum(_tpf_active_samples_per_fwd) / len(_tpf_active_samples_per_fwd)
                if _tpf_active_samples_per_fwd else 0.0
            )
            self._last_tpf_stats = {
                'batch_size': batch_size,
                'mrp_steps': int(mrp_steps),
                'use_mrp': bool(use_mrp),
                'block_length': int(block_length),
                'denoising_steps': int(denoising_steps),
                # counters
                'num_target_fwd_prefill': _tpf_counters['num_target_fwd_prefill'],
                'num_target_fwd_denoising': num_target_fwd_denoising,
                'num_target_fwd_store_kv': _tpf_counters['num_target_fwd_store_kv'],
                'num_target_fwd_total': num_target_fwd_total,
                'num_mrp_fwd_prefill': _tpf_counters['num_mrp_fwd_prefill'],
                'num_mrp_fwd_denoising': _tpf_counters['num_mrp_fwd_denoising'],
                'num_mrp_fwd_store_kv': _tpf_counters['num_mrp_fwd_store_kv'],
                'num_blocks_decoded': _tpf_counters['num_blocks_decoded'],
                # tokens
                'total_tokens_committed': total_tokens,
                'total_tokens_by_target': total_tokens_by_target,
                'total_tokens_by_mrp': total_tokens_by_mrp,
                'total_mrp_tokens_proposed': total_mrp_tokens_proposed,
                'mrp_accept_rate': mrp_accept_rate,
                'per_sample_tokens': per_sample_tokens,
                'per_sample_tokens_by_target': tokens_by_target,
                'per_sample_tokens_by_mrp': tokens_by_mrp,
                # derived metrics
                'tpf_denoising': tpf_denoising,
                'tpf_end_to_end': tpf_end_to_end,
                'ideal_tpf_denoising': ideal_tpf_denoising,
                'avg_active_samples_per_denoising_fwd': avg_active_samples_per_fwd,
                'active_samples_per_denoising_fwd': _tpf_active_samples_per_fwd,
                'per_iter_trace': _tpf_per_iter_trace,
            }

        return x

    @torch.no_grad()
    def _generate_residual_remask(
        self,
        input_ids,
        mask_id,
        attention_mask,
        max_length,
        block_length,
        denoising_steps,
        temperature,
        top_k,
        top_p,
        confidence_threshold,
        residual_delta,
        stopping_criteria,
        stopping_criteria_idx,
        verbose=False,
    ):
        """MRP-as-vetoer decoding: aggressive target unmask + residual remask.

        Per denoising step within a block:

          1. Target forward on the current (masked) block state -> target
             logits + h_A. Aggressively commit every still-masked position
             whose confidence exceeds ``confidence_threshold`` (low threshold);
             per-sample fallback to top-1 so a step always proposes >= 1.
          2. ONE MRP forward, seeded by h_A on the same pre-commit state ->
             raw logit-space residual ``C`` (its prediction; NOT mixed with
             the target logits).
          3. Per-token veto: drop any proposed commit whose
             ``|C[pos, committed_id]| > residual_delta`` (it's unstable; let it
             resolve later with more context). Progress guard keeps the
             smallest-|C| proposal per sample if all are vetoed.
          4. Commit the survivors; repeat until the block is fully revealed.

        MRP never samples or commits — it only remasks. Cost is 1 target +
        1 MRP forward per denoising step (plus prefill / store-kv target fwds),
        mirroring the standard dynamic decode with an extra MRP veto forward.
        """
        self.eval()
        BL = int(block_length)
        device = input_ids.device
        bsz = input_ids.shape[0]
        mask_id = mask_id if mask_id is not None else self.config.mask_token_id

        if attention_mask is not None:
            prompt_lengths = attention_mask.sum(dim=1).long()
            prompt_length = int(prompt_lengths.min().item())
        else:
            prompt_lengths = torch.full(
                (bsz,), input_ids.shape[1], dtype=torch.long, device=device,
            )
            prompt_length = input_ids.shape[1]
        past_key_values = DynamicCache()

        initial_length = input_ids.shape[1]
        generation_length = max(initial_length, prompt_length + max_length)
        num_blocks = (generation_length + BL - 1) // BL
        total_length = num_blocks * BL

        block_mask = torch.tril(torch.ones(num_blocks, num_blocks, device=device))
        block_diffusion_attention_mask = (
            block_mask.repeat_interleave(BL, dim=0)
                     .repeat_interleave(BL, dim=1).unsqueeze(0)
        )
        position_ids = torch.arange(total_length, device=device).unsqueeze(0).expand(bsz, -1)

        x = torch.full((bsz, total_length), mask_id, dtype=torch.long, device=device)
        if attention_mask is not None:
            prompt_token_mask = torch.zeros((bsz, total_length), dtype=torch.bool, device=device)
            prompt_token_mask[:, :initial_length] = attention_mask.bool()
            x[:, :initial_length] = torch.where(
                prompt_token_mask[:, :initial_length], input_ids, x[:, :initial_length],
            )
        else:
            x[:, :initial_length] = input_ids
        prefill_blocks = prompt_length // BL
        prefill_length = prefill_blocks * BL

        profile_tpf = bool(getattr(self, '_profile_tpf', False))
        if profile_tpf:
            _tpf = {
                'num_target_fwd_prefill': 0,
                'num_target_fwd_denoising': 0,
                'num_target_fwd_store_kv': 0,
                'num_mrp_fwd_denoising': 0,
                'num_blocks_decoded': 0,
                'num_committed': 0,
                'num_vetoed': 0,
            }

        # Prefill (target-only, like the spec paths).
        if prefill_length > 0:
            cur_x = x[:, :prefill_length]
            cur_attn_mask = block_diffusion_attention_mask[:, :prefill_length, :prefill_length]
            cur_position_ids = position_ids[:, :prefill_length]
            _ = self(cur_x,
                attention_mask=cur_attn_mask,
                position_ids=cur_position_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=False,
            )
            if profile_tpf:
                _tpf['num_target_fwd_prefill'] += 1

        finished = torch.zeros(bsz, dtype=torch.bool, device=device)
        batch_idx = torch.arange(bsz, device=device)

        def _check_stopping():
            if stopping_criteria_idx is not None:
                token_positions = torch.arange(total_length, device=device).unsqueeze(0)
                generated_mask = token_positions >= prompt_lengths.unsqueeze(1)
                for stop_idx in stopping_criteria_idx:
                    finished.copy_(finished | ((x == stop_idx) & generated_mask).any(dim=1))
            if stopping_criteria is not None:
                should_stop = stopping_criteria(x, None)
                if isinstance(should_stop, torch.Tensor):
                    if should_stop.ndim == 0:
                        if should_stop.item():
                            finished[:] = True
                    elif should_stop.all().item():
                        finished[:] = True
                elif should_stop:
                    finished[:] = True

        is_main = int(os.environ.get("LOCAL_RANK", 0)) == 0
        block_iter = range(prefill_blocks, num_blocks)
        pbar = tqdm(block_iter, desc=f"ResidualRemask block {prefill_blocks}/{num_blocks}") \
            if (verbose and is_main) else block_iter

        for num_block in pbar:
            cur_x = x[:, num_block*BL:(num_block+1)*BL].clone()
            block_attn_mask = block_diffusion_attention_mask[
                :, num_block*BL:(num_block+1)*BL, :(num_block+1)*BL,
            ]
            block_pos_ids = position_ids[:, num_block*BL:(num_block+1)*BL]
            if profile_tpf:
                _tpf['num_blocks_decoded'] += 1

            # Denoising steps for this block (bounded by denoising_steps; the
            # while-condition exits early once the block is fully revealed).
            for _step in range(denoising_steps):
                mask_index = (cur_x == mask_id) & (~finished.unsqueeze(1))
                if not mask_index.any():
                    break

                # --- Target forward: aggressive dynamic unmask. ---
                tgt_out = self(cur_x,
                    attention_mask=block_attn_mask,
                    position_ids=block_pos_ids,
                    past_key_values=past_key_values,
                    use_cache=True,
                    store_kv=False,
                    use_mrp=False,
                    output_hidden_states=True,
                )
                if profile_tpf:
                    _tpf['num_target_fwd_denoising'] += 1
                target_logits = tgt_out.logits.to(device)
                target_hidden = self._mrp_anchor(tgt_out)

                x0, x0_p = sample_with_temperature_topk_topp(
                    target_logits, temperature=temperature, top_k=top_k, top_p=top_p,
                )
                confidence = torch.where(
                    mask_index, x0_p, torch.full_like(x0_p, float('-inf')),
                )
                high_conf = confidence > confidence_threshold
                transfer_index = torch.zeros_like(x0, dtype=torch.bool)
                for j in range(bsz):
                    if not mask_index[j].any():
                        continue
                    if high_conf[j].any():
                        transfer_index[j] = high_conf[j]
                    else:
                        # Fallback: top-1, so the target always proposes >= 1.
                        _, idx = torch.topk(confidence[j], 1)
                        transfer_index[j, idx] = True
                transfer_index[finished] = False

                # --- MRP veto: one MRP forward for the residual C, then remask
                #     any proposed commit whose |C[pos, committed_id]| > delta. ---
                if transfer_index.any():
                    mrp_out = self.mrp_modules[0](
                        embed_tokens=self.model.embed_tokens,
                        lm_head=self.lm_head,
                        input_ids=cur_x,
                        inputs_embeds=target_hidden,
                        attention_mask=block_attn_mask,
                        position_ids=block_pos_ids,
                        past_key_values=past_key_values,
                        use_cache=True,
                        store_kv=False,
                    )
                    if profile_tpf:
                        _tpf['num_mrp_fwd_denoising'] += 1
                    residual_logits = mrp_out.logits.to(device)

                    # Optional: collect the veto scalar |C[pos, committed_id]|
                    # for every PROPOSED commit (the population the veto draws
                    # from). Run with a huge residual_delta to veto nothing and
                    # get the δ-independent distribution. Guarded so the normal
                    # path is unchanged.
                    if bool(getattr(self, '_profile_residual_remask', False)):
                        _c_tok = residual_logits.gather(
                            -1, x0.long().unsqueeze(-1),
                        ).squeeze(-1)                       # [B, L]
                        _mags = _c_tok.abs()[transfer_index]  # 1D over proposals
                        if not hasattr(self, '_residual_remask_mags'):
                            self._residual_remask_mags = []
                        self._residual_remask_mags.append(
                            _mags.detach().float().cpu()
                        )

                    proposed = int(transfer_index.sum().item()) if profile_tpf else 0
                    transfer_index = residual_remask_transfer(
                        transfer_index, x0, residual_logits, residual_delta,
                    )
                    if profile_tpf:
                        kept = int(transfer_index.sum().item())
                        _tpf['num_committed'] += kept
                        _tpf['num_vetoed'] += proposed - kept

                cur_x[transfer_index] = x0[transfer_index]

            # Block done — store its KV.
            _ = self(cur_x,
                attention_mask=block_attn_mask,
                position_ids=block_pos_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=False,
            )
            if profile_tpf:
                _tpf['num_target_fwd_store_kv'] += 1
            x[:, num_block*BL:(num_block+1)*BL] = cur_x

            _check_stopping()
            if finished.all():
                break

        if profile_tpf:
            num_target_fwd_total = (
                _tpf['num_target_fwd_prefill']
                + _tpf['num_target_fwd_denoising']
                + _tpf['num_target_fwd_store_kv']
            )
            self._last_tpf_stats = {
                'batch_size': bsz,
                'mrp_steps': 1,
                'use_mrp': False,
                'block_length': int(BL),
                'denoising_steps': int(denoising_steps),
                'num_target_fwd_prefill': _tpf['num_target_fwd_prefill'],
                'num_target_fwd_denoising': _tpf['num_target_fwd_denoising'],
                'num_target_fwd_store_kv': _tpf['num_target_fwd_store_kv'],
                'num_target_fwd_total': num_target_fwd_total,
                'num_mrp_fwd_prefill': 0,
                'num_mrp_fwd_denoising': _tpf['num_mrp_fwd_denoising'],
                'num_mrp_fwd_store_kv': 0,
                'num_blocks_decoded': _tpf['num_blocks_decoded'],
                # All commits are the target's; MRP only vetoes.
                'total_tokens_committed': _tpf['num_committed'],
                'total_tokens_by_target': _tpf['num_committed'],
                'total_tokens_by_mrp': 0,
                # residual_remask-specific accounting.
                'num_residual_vetoed': _tpf['num_vetoed'],
            }

        return x

    @torch.no_grad()
    def _generate_spec(
        self,
        input_ids,
        mask_id,
        attention_mask,
        max_length,
        block_length,
        denoising_steps,
        temperature,
        top_k,
        top_p,
        remasking_strategy,
        confidence_threshold,
        eb_threshold,
        stopping_criteria,
        stopping_criteria_idx,
        K,
        mrp_logit_mix_mode='none',
        mrp_logit_sum_scale=1.0,
        verbose=False,
    ):
        """Within-block vanilla speculative-decoding path (panel (d)).

        Per anchor block, denoise it via repeated "spec rounds" until fully
        revealed. Each spec round:

          1. Target forward on the current block state → ``target_logits``,
             ``target_hidden`` (h_A). One commit (the bonus / first MRP iter
             seed) comes from these logits.
          2. K-1 MRP draft iterations. Iter j (j = 1..K-1) uses the
             previous iter's hidden state as ``inputs_embeds``; each iter
             samples its own logits, picks the highest-confidence still-masked
             position via ``low_confidence_static`` (n=1), and commits one
             token there.
          3. Pack ``K+1`` candidate states ``[C(0) | C(1) | ... | C(K)]``
             (C(k) = block with k draft tokens revealed) and run ONE target
             verify forward with a block-diagonal attention mask.
          4. Greedy ``(position, token)`` accept: walk k = 0..K-1; at
             candidate k, target's ``low_confidence_static`` pick must equal
             the MRP draft made at step k+1. First mismatch stops the
             chain. Batch policy: batch-min so all samples advance together.
          5. Commit the accepted ``j`` drafts (cur_x ← C(j)). Bonus: read
             target's pick at candidate ``j`` (already in the verify pass)
             and commit it for free — that's the autoregressive
             spec-dec-equivalent bonus token. Total tokens per round:
             ``j + 1`` (up to ``K`` when all drafts accepted).

        ``K`` here is the number of MRP draft iterations per spec round
        (= ``mrp_steps``). The verify pass contains ``K+1`` candidate states.
        """
        self.eval()
        BL = int(block_length)
        device = input_ids.device
        bsz = input_ids.shape[0]
        mask_id = mask_id if mask_id is not None else self.config.mask_token_id

        if attention_mask is not None:
            prompt_lengths = attention_mask.sum(dim=1).long()
            prompt_length = int(prompt_lengths.min().item())
        else:
            prompt_lengths = torch.full(
                (bsz,), input_ids.shape[1], dtype=torch.long, device=device,
            )
            prompt_length = input_ids.shape[1]
        past_key_values = DynamicCache()

        initial_length = input_ids.shape[1]
        generation_length = max(initial_length, prompt_length + max_length)
        num_blocks = (generation_length + BL - 1) // BL
        total_length = num_blocks * BL

        block_mask = torch.tril(torch.ones(num_blocks, num_blocks, device=device))
        block_diffusion_attention_mask = (
            block_mask.repeat_interleave(BL, dim=0)
                     .repeat_interleave(BL, dim=1).unsqueeze(0)
        )
        position_ids = torch.arange(total_length, device=device).unsqueeze(0).expand(bsz, -1)

        x = torch.full((bsz, total_length), mask_id, dtype=torch.long, device=device)
        if attention_mask is not None:
            prompt_token_mask = torch.zeros((bsz, total_length), dtype=torch.bool, device=device)
            prompt_token_mask[:, :initial_length] = attention_mask.bool()
            x[:, :initial_length] = torch.where(
                prompt_token_mask[:, :initial_length], input_ids, x[:, :initial_length],
            )
        else:
            x[:, :initial_length] = input_ids
        prefill_blocks = prompt_length // BL
        prefill_length = prefill_blocks * BL

        profile_tpf = bool(getattr(self, '_profile_tpf', False))
        if profile_tpf:
            _tpf = {
                'num_target_fwd_prefill': 0,
                'num_target_fwd_denoising': 0,    # round-initial target fwds (h_A)
                'num_target_fwd_verify': 0,       # round-verify target fwds
                'num_target_fwd_store_kv': 0,
                'num_mrp_fwd_draft': 0,
                'num_blocks_decoded': 0,
                'num_spec_rounds': 0,
                'num_drafts_proposed': 0,
                'num_drafts_accepted': 0,
                'num_bonus_tokens': 0,
            }

        # Prefill.
        if prefill_length > 0:
            cur_x = x[:, :prefill_length]
            cur_attn_mask = block_diffusion_attention_mask[:, :prefill_length, :prefill_length]
            cur_position_ids = position_ids[:, :prefill_length]
            _ = self(cur_x,
                attention_mask=cur_attn_mask,
                position_ids=cur_position_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=False,
            )
            if profile_tpf:
                _tpf['num_target_fwd_prefill'] += 1

        block_ptr = prefill_blocks
        finished = torch.zeros(bsz, dtype=torch.bool, device=device)

        is_main = int(os.environ.get("LOCAL_RANK", 0)) == 0
        pbar = tqdm(total=num_blocks - prefill_blocks,
                    desc=f"Spec block {prefill_blocks}/{num_blocks}") if (verbose and is_main) else None

        def _check_stopping():
            nonlocal finished
            if stopping_criteria_idx is not None:
                token_positions = torch.arange(total_length, device=device).unsqueeze(0)
                generated_mask = token_positions >= prompt_lengths.unsqueeze(1)
                for stop_idx in stopping_criteria_idx:
                    finished |= ((x == stop_idx) & generated_mask).any(dim=1)
            if stopping_criteria is not None:
                should_stop = stopping_criteria(x, None)
                if isinstance(should_stop, torch.Tensor):
                    if should_stop.ndim == 0:
                        if should_stop.item():
                            finished[:] = True
                    elif should_stop.all().item():
                        finished[:] = True
                elif should_stop:
                    finished[:] = True

        if remasking_strategy != 'low_confidence_static':
            logger.warning_once(
                f"_generate_spec uses 'low_confidence_static' for in-round "
                f"commits; requested '{remasking_strategy}' is ignored."
            )

        batch_idx = torch.arange(bsz, device=device)

        def _pick_low_conf_static(state_for_mask, logits):
            """Greedy ``low_confidence_static`` (n=1) pick per sample.

            Returns ``(pick_pos[B], pick_tok[B], pick_valid[B])`` where
            ``pick_valid`` is False for samples with no masked positions
            (or finished). Invalid picks are zeroed and the caller must skip
            commits for those samples.
            """
            x0, x0_p = sample_with_temperature_topk_topp(
                logits, temperature=temperature, top_k=top_k, top_p=top_p,
            )
            mask_index = (state_for_mask == mask_id) & (~finished.unsqueeze(1))
            confidence = torch.where(
                mask_index, x0_p, torch.full_like(x0_p, float('-inf')),
            )
            pick_pos = confidence.argmax(dim=-1)        # [B]
            pick_tok = x0[batch_idx, pick_pos]          # [B]
            pick_valid = mask_index.any(dim=-1)         # [B]
            return pick_pos, pick_tok, pick_valid

        block_ptr_outer = prefill_blocks
        while block_ptr_outer < num_blocks and not finished.all():
            block_ptr = block_ptr_outer
            prefix_len = block_ptr * BL
            cur_x = x[:, block_ptr*BL:(block_ptr+1)*BL].clone()
            block_attn_mask = block_diffusion_attention_mask[
                :, block_ptr*BL:(block_ptr+1)*BL, :(block_ptr+1)*BL,
            ]
            block_pos_ids = position_ids[:, block_ptr*BL:(block_ptr+1)*BL]
            if profile_tpf:
                _tpf['num_blocks_decoded'] += 1

            # Initial seed forward for this block: target_logits (seed for
            # MRP iter 1's pick) and target_hidden (h_A — seed for MRP iter
            # 2's inputs_embeds). Rounds 2+ reuse the verify forward's
            # accepted-candidate slice as their seed instead of re-forwarding
            # (~1 target fwd/round instead of 2).
            seed_out = self(cur_x,
                attention_mask=block_attn_mask,
                position_ids=block_pos_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=False,
                use_mrp=False,
                output_hidden_states=True,
            )
            if profile_tpf:
                _tpf['num_target_fwd_denoising'] += 1
            target_logits = seed_out.logits.to(device)
            # Step-1 anchor: fused projection P when fusion is on, else h_A.
            target_hidden = self._mrp_anchor(seed_out)

            # Spec rounds until the anchor block is fully revealed (or
            # all samples finished).
            while ((cur_x == mask_id) & (~finished.unsqueeze(1))).any():
                if profile_tpf:
                    _tpf['num_spec_rounds'] += 1

                # Phase 1: target_logits / target_hidden are the round seed —
                # from the initial seed forward (round 1) or the previous
                # round's verify forward (rounds 2+). No forward here.

                # ----------------------------------------------------------
                # Phase 2: K MRP draft iterations.
                # Iter 1 picks from target_logits (no MRP fwd before).
                # Iter j>1 runs MRP fwd on the post-iter-(j-1) state to get
                # its own logits, then picks. K-1 MRP forwards total for K
                # drafts.
                # ----------------------------------------------------------
                candidate_states = [cur_x.clone()]          # C(0)
                draft_picks = []                            # list of (pos, tok, valid) per iter

                # Logit-aggregation state, mirrors the per-iter MRP loop.
                # Under 'logits_sum' (the training-matched mode for residual-
                # predicting MRP heads, e.g. the k2 ckpts), each MRP iter
                # adds to a running logit accumulator and the hidden input
                # is the running hidden accumulator (h_A + Σ h_p). Under
                # 'none' we just chain prev mrp_hidden as inputs_embeds and
                # sample from raw mrp_logits (wrong for residual heads).
                cur_logits = target_logits
                cur_hidden = target_hidden
                target_logits_for_agg = target_logits  # immutable seed
                prev_logits_for_agg = target_logits    # accumulator
                hidden_acc = target_hidden             # running h_A + Σ h_p

                for j in range(K):
                    pick_pos, pick_tok, pick_valid = _pick_low_conf_static(
                        candidate_states[-1], cur_logits,
                    )
                    # Commit pick to produce next candidate state.
                    new_state = candidate_states[-1].clone()
                    # Only commit for samples with a valid pick.
                    if pick_valid.any():
                        valid_b = pick_valid.nonzero(as_tuple=True)[0]
                        new_state[valid_b, pick_pos[valid_b]] = pick_tok[valid_b]
                    candidate_states.append(new_state)
                    draft_picks.append((pick_pos, pick_tok, pick_valid))
                    if profile_tpf:
                        _tpf['num_drafts_proposed'] += int(pick_valid.sum().item())

                    # Need MRP fwd before the NEXT iter to get its logits
                    # (skip after the final iter).
                    if j == K - 1:
                        break
                    # logits_sum: feed the cumulative hidden accumulator,
                    # not the per-iter h_p (matches training: MRP head sees
                    # h_A + Σ_{i<k} h_p_i for iter k).
                    mrp_inputs_embeds = (
                        hidden_acc if mrp_logit_mix_mode == 'logits_sum'
                        else cur_hidden
                    )
                    mrp_out = self.mrp_modules[0](
                        embed_tokens=self.model.embed_tokens,
                        lm_head=self.lm_head,
                        input_ids=new_state,
                        inputs_embeds=mrp_inputs_embeds,
                        attention_mask=block_attn_mask,
                        position_ids=block_pos_ids,
                        past_key_values=past_key_values,
                        use_cache=True,
                        store_kv=False,
                        output_hidden_states=True,
                    )
                    if profile_tpf:
                        _tpf['num_mrp_fwd_draft'] += 1
                    raw_mrp_logits = mrp_out.logits.to(device)
                    new_hidden = mrp_out.hidden_states[-1]
                    # Update accumulators.
                    if mrp_logit_mix_mode == 'logits_sum':
                        hidden_acc = hidden_acc + mrp_logit_sum_scale * new_hidden
                    # Logit aggregation for the NEXT iter's sampling.
                    if mrp_logit_mix_mode == 'none':
                        cur_logits = raw_mrp_logits
                    else:
                        cur_logits = self._mrp_aggregate(
                            mrp_logit_mix_mode, raw_mrp_logits,
                            target_logits_for_agg, prev_logits_for_agg,
                            sum_scale=mrp_logit_sum_scale,
                        )
                        prev_logits_for_agg = cur_logits.detach()
                    cur_hidden = new_hidden

                # ----------------------------------------------------------
                # Phase 3: target verify forward over K+1 packed candidates.
                # Each candidate shares the same block position_ids; mask is
                # block-diagonal with full prefix attention.
                # ----------------------------------------------------------
                K1 = len(candidate_states)                          # K+1 normally
                packed_input = torch.stack(candidate_states, dim=1)  # [B, K+1, BL]
                packed_input = packed_input.view(bsz, K1 * BL)
                packed_pos_ids = block_pos_ids.repeat(1, K1)         # [B, K+1*BL]
                # Shape [1, L_q, L_k] — SDPA broadcasts across batch + heads.
                # Do NOT expand to [B, L, L]; that aligns dim 0 with H and
                # explodes when B != H (PyTorch broadcasts from the right).
                verify_attn_mask = build_spec_verification_mask(
                    prefix_len=prefix_len, num_candidates=K1,
                    block_length=BL, device=device,
                )
                verify_out = self(packed_input,
                    attention_mask=verify_attn_mask,
                    position_ids=packed_pos_ids,
                    past_key_values=past_key_values,
                    use_cache=True,
                    store_kv=False,
                    use_mrp=False,
                    output_hidden_states=True,
                )
                if profile_tpf:
                    _tpf['num_target_fwd_verify'] += 1
                verify_logits = verify_out.logits.to(device)  # [B, K1*BL, V]
                verify_hidden = verify_out.hidden_states[-1]  # [B, K1*BL, H]

                # ----------------------------------------------------------
                # Phase 4: greedy (position, token) accept.
                # At candidate k, target's low_confidence_static pick must
                # equal MRP's draft at step k+1.
                # ----------------------------------------------------------
                accepted = 0
                # Per-candidate target picks for accept-check + bonus.
                target_picks = []  # list of (pos[B], tok[B], valid[B]) per candidate
                for k in range(K1):
                    cand_logits = verify_logits[:, k*BL:(k+1)*BL, :]
                    t_pos, t_tok, t_valid = _pick_low_conf_static(
                        candidate_states[k], cand_logits,
                    )
                    target_picks.append((t_pos, t_tok, t_valid))

                for k in range(K):
                    mrp_pos, mrp_tok, mrp_valid = draft_picks[k]
                    t_pos, t_tok, t_valid = target_picks[k]
                    # Samples with no valid pick on either side: vacuously
                    # match (they've finished or run out of masks). The
                    # outer mask_index gate handles their commits.
                    both_inactive = (~mrp_valid) & (~t_valid)
                    match = (mrp_pos == t_pos) & (mrp_tok == t_tok)
                    match = match | both_inactive
                    if not bool(match.all().item()):
                        break
                    accepted += 1

                # ----------------------------------------------------------
                # Phase 5: commit accepted drafts + bonus.
                # cur_x ← C(accepted); then commit target's pick at
                # candidate `accepted` as the bonus (already computed).
                # ----------------------------------------------------------
                cur_x = candidate_states[accepted].clone()
                if profile_tpf:
                    _tpf['num_drafts_accepted'] += accepted

                # Bonus: target's pick at candidate `accepted`. This is the
                # per-round progress guarantee (spec mode has no Phase-A
                # commit), so we keep it even with the fused reseed below.
                bonus_pos, bonus_tok, bonus_valid = target_picks[accepted]
                bonus_mask_index = (cur_x == mask_id) & (~finished.unsqueeze(1))
                # Per-sample bonus commit (only if the picked position is
                # actually still a mask for that sample after applying
                # accepted drafts — should hold by construction).
                if bonus_valid.any() and bonus_mask_index.any():
                    valid_b = bonus_valid.nonzero(as_tuple=True)[0]
                    # Filter: only commit if the bonus position is masked
                    # in the post-accept state (sanity guard).
                    pos_is_mask = bonus_mask_index[valid_b, bonus_pos[valid_b]]
                    safe_b = valid_b[pos_is_mask]
                    if safe_b.numel() > 0:
                        cur_x[safe_b, bonus_pos[safe_b]] = bonus_tok[safe_b]
                        if profile_tpf:
                            _tpf['num_bonus_tokens'] += int(safe_b.numel())

                # Reseed the next round from the verify forward's accepted
                # slice (logits + h_A), instead of re-forwarding the anchor.
                # MRP iter 1 next round picks from these logits and conditions
                # on this hidden — the target forward over C(accepted) is
                # exactly what a round-initial Phase-1 forward would recompute.
                target_logits = verify_logits[:, accepted*BL:(accepted+1)*BL, :]
                # Re-anchor the next round from the verify forward. Fuse over
                # the verify target states (or its final hidden when fusion is
                # off) before slicing the accepted block.
                verify_anchor = self._mrp_anchor(verify_out)
                target_hidden = verify_anchor[:, accepted*BL:(accepted+1)*BL, :]

                # Loop back: another spec round on the partially-denoised
                # block, unless it's fully clean now.

            # Block fully denoised — store its KV and move on.
            _ = self(cur_x,
                attention_mask=block_attn_mask,
                position_ids=block_pos_ids,
                past_key_values=past_key_values,
                use_cache=True,
                store_kv=True,
                use_mrp=False,
            )
            if profile_tpf:
                _tpf['num_target_fwd_store_kv'] += 1
            x[:, block_ptr*BL:(block_ptr+1)*BL] = cur_x
            block_ptr_outer += 1
            if pbar is not None:
                pbar.update(1)
                pbar.set_description(f"Spec block {block_ptr_outer}/{num_blocks}")

            _check_stopping()

        if pbar is not None:
            pbar.close()

        if profile_tpf:
            num_target_fwd_denoising = (
                _tpf['num_target_fwd_denoising'] + _tpf['num_target_fwd_verify']
            )
            num_target_fwd_total = (
                _tpf['num_target_fwd_prefill']
                + num_target_fwd_denoising
                + _tpf['num_target_fwd_store_kv']
            )
            self._last_tpf_stats = {
                'batch_size': bsz,
                'mrp_steps': int(K),
                'use_mrp': False,
                'block_length': int(BL),
                'denoising_steps': int(denoising_steps),
                'num_target_fwd_prefill': _tpf['num_target_fwd_prefill'],
                'num_target_fwd_denoising': num_target_fwd_denoising,
                'num_target_fwd_store_kv': _tpf['num_target_fwd_store_kv'],
                'num_target_fwd_total': num_target_fwd_total,
                'num_mrp_fwd_prefill': 0,
                'num_mrp_fwd_denoising': _tpf['num_mrp_fwd_draft'],
                'num_mrp_fwd_store_kv': 0,
                'num_blocks_decoded': _tpf['num_blocks_decoded'],
                # spec-specific
                'num_spec_rounds': _tpf['num_spec_rounds'],
                'num_drafts_proposed': _tpf['num_drafts_proposed'],
                'num_drafts_accepted': _tpf['num_drafts_accepted'],
                'num_bonus_tokens': _tpf['num_bonus_tokens'],
                'spec_draft_accept_rate': (
                    _tpf['num_drafts_accepted'] / _tpf['num_drafts_proposed']
                    if _tpf['num_drafts_proposed'] > 0 else 0.0
                ),
            }

        return x



__all__ = [
    "SDARMRPForCausalLM",
    "SDARMRPModel",
    "SDARMRPPreTrainedModel",
]
